window.marchStdlib = window.marchStdlib || {};
window.marchStdlib["session_node.march"] = "-- SessionNode: the `Session.Ops` network transport. A protocol's\n-- `@[endpoints]` roles run on two or more nodes, one connection per pair\n-- (distributed actors, step 4 of specs/progress/2026-09-15-remote-actor-dispatch.md;\n-- multiparty routing: specs/progress/2026-09-16-session-node-multiparty-routing.md).\n--\n-- The transport is protocol-independent: `Session.Ops` speaks in endpoint\n-- ids (Int) and encoded messages (Bytes, the generated `<P>_Msg.encode`), so\n-- nothing here names a protocol's constructors and nothing needs generating.\n-- Roles are numbered 1..n by the generator (`<P>_Msg.role_<R>()`) and\n-- `register` returns the role as the endpoint id, so an endpoint id IS its\n-- role: `emit`'s `to` names the remote role, and that is what picks the\n-- connection.\n--\n-- Two nodes:\n--\n--   let p = SessionNode.open(conn, \"node-a\", false, fn ep -> ())   -- after connect_split / accept_split\n--   let s = Session.attach(io, SessionNode.ops(p))\n--   ... drive the role to its first suspension ...\n--   SessionNode.serve(p)          -- deliveries, until every peer's endpoint closes\n--   SessionNode.finish(p)\n--\n-- Three or more: one `party`, then one join per peer. The side that ACCEPTS\n-- learns the peer's role from its hello (a listener does not know which role\n-- will connect next); the side that connects names it.\n--\n--   let p0 = SessionNode.party(Relay_Msg.role_B(), \"node-b\", fn ep -> ())\n--   let p1 = SessionNode.accept_from(p0, conn_from_a)\n--   let p  = SessionNode.connect_to(p1, Relay_Msg.role_C(), conn_to_c)\n--\n-- Connect rule, so no configuration and no deadlock: for roles i < j, i\n-- listens and j connects.\n--\n-- On the wire, per peer connection (the control/data split):\n--   data     ACTOR_MSG \"SessionNode.Deliver\" [to, from, msg], through a\n--            NodeQueue (credit-based flow control); \"SessionNode.Bye\" when an\n--            endpoint closes. D27 drains add a fourth Deliver element (1: the\n--            sender's epoch is draining, sent only while it is),\n--            \"SessionNode.Undelivered\" [to, from, msg] (a message of [to]'s\n--            that [from] drained without consuming, going back) and\n--            \"SessionNode.Drained\" [role] (that role's endpoint drained; its\n--            Bye follows once the peer's own end has arrived).\n--   control  \"SessionNode.Hello\" [role, pid] (the ACCEPTING side announces\n--            first), CREDIT, and a final Bye.\n--\n-- Receiving: a delivery is sent to this node's endpoint actor, whose turn\n-- runs the continuation `suspend` installed. ONE actor per party, whatever\n-- the number of peers, so a node's resumptions (and prints) run in mailbox\n-- order. \"Consumed\" for credit is \"in the mailbox\".\n--\n-- Ordering: each connection is FIFO, but messages from DIFFERENT peers race.\n-- A role that receives from A and then from B can see B's delivery first, so\n-- `suspend` takes the role the continuation expects and a delivery from\n-- anyone else is parked until the continuation that wants it is installed\n-- (`pending`). `suspend`'s expected role is 0 for \"any\", which is what a\n-- same-thread transport and a two-party session pass.\n--\n-- Failure (specs/todos/2026-09-18-choreography-failure-handling.md, after\n-- Maty's affine sessions): a role that fails is CANCELLED. Its node sends a\n-- `SessionNode.Cancel` frame on each data connection, behind everything\n-- it already sent, and a dropped connection counts as one at that point in\n-- the stream. Messages to a cancelled role are discarded. A local endpoint\n-- fails only when its continuation waits on a role that can send nothing\n-- more and nothing from that role is still queued; its cancel handler then\n-- runs and it is cancelled in turn, which is how failure cascades. Every\n-- one of these events goes through the endpoint actor's mailbox, behind the\n-- deliveries that preceded it, so the \"handle what was already sent\" rule\n-- holds by construction. A heartbeat on each data connection catches a\n-- peer that stops without closing.\n--\n-- The role runner (`run`, at the end of this file) does all of the above\n-- from a role, its peer set and a role->address table, in the order that\n-- cannot deadlock; the generated `<P>_Run.run_<Role>` is its typed front.\n-- `run_hosted` is the same party driving a role hosted in an actor (the\n-- generated event API) -- `<P>_Run.host_<Role>`.\n-- Design: specs/progress/2026-09-16-role-runner.md and\n-- specs/progress/2026-09-17-actor-hosted-runner.md.\nmod SessionNode do\n  needs IO\n  needs IO.Mut\n  needs IO.NetConnect\n  needs IO.NetListen\n  needs IO.Process\n  needs IO.Spawn\n  needs Session.Live\n  needs ClusterNode.Live\n\n  pfn budget() : Int do 4096 end\n\n  -- One peer connection: the remote role it reaches and everything that\n  -- connection owns.\n  type Link = { role : Int, data_fd : Int, control_fd : Int, peer : GlobalPid.Pid,\n                q : (Pid(NodeQueue.WriterState), Int), control : Task(Int) }\n\n  -- The endpoint actor's state: the delivery count, and the readers'\n  -- outcomes `serve_outcome` waits on (see the actor below).\n  type EndpointState = { n : Int, links : Int, ended : Int, failed : List((Int, String)),\n                         waiters : List(List((Int, String)) -> Unit) }\n\n  -- The whole session on this node. `handlers` holds the installed\n  -- continuation per local endpoint and `waiting` the role each expects;\n  -- `pending` holds deliveries that arrived before their continuation.\n  -- `meta` carries the send seq, the closed flag and the host-gone flag.\n  -- `forward` (key \"f\") is set only for a HOSTED party (`run_hosted`): a\n  -- delivery for an awaiting endpoint then goes to the user's actor through\n  -- it, instead of the installed handler running here, and the actor\n  -- resumes the endpoint itself (the generated event API).\n  --\n  -- Failure state: `gone` maps a peer role that can send nothing more to\n  -- why (\"closed\" for a normal close, else the cancellation cause);\n  -- `cancel_hs` holds the cancel handler installed with the current\n  -- continuation (`Session.on_cancel`); `crash_hs` the crash continuation\n  -- installed with it (`Session.on_crash`), under the endpoint AND the role\n  -- it is for (`crash_key`); `forward_cancel` (key \"c\") is the\n  -- hosted party's way to tell its actor that its endpoint was cancelled and\n  -- `forward_crash` (key \"x\") its way to tell it that a role it waits on\n  -- crashed, so the actor takes the crash branch itself (the crash arrives\n  -- on the delivery route, as `Session.crash_payload`, and the generated\n  -- `resume` turns it into a `Crashed_\u2026` event); `heard` counts heartbeat ticks\n  -- since a peer's last frame. Our own endpoint's end is in `meta`: \"done\"\n  -- once it closed or was cancelled, and for a cancellation \"kind\"\n  -- (see `cancel_endpoint`), \"cancel_role\", and `why`'s \"cancel_cause\".\n  type Party = { my_role : Int, node_id : String,\n                 handlers : Vault(Int -> Bytes -> Int -> Int), waiting : Vault(Int),\n                 pending : Vault(List((Int, Bytes))), meta : Vault(Int),\n                 forward : Vault(Int -> Bytes -> Int -> Unit), why : Vault(String),\n                 gone : Vault(String), cancel_hs : Vault(Int -> String -> Int -> Int),\n                 crash_hs : Vault(Int -> String -> Int -> Int),\n                 forward_cancel : Vault(Int -> String -> Int -> Unit),\n                 forward_crash : Vault(Int -> String -> Int -> Unit), heard : Vault(Int),\n                 drain_hs : Vault(Int -> List(Bytes) -> Int -> Int),\n                 ep : Pid(EndpointState), links : List(Link), on_close : Int -> Unit }\n\n  pfn ekey(ep : Int) : String do \"e\" ++ int_to_string(ep) end\n  pfn crash_key(ep : Int, role : Int) : String do ekey(ep) ++ \"/r\" ++ int_to_string(role) end\n\n  pfn encode_deliver(to : Int, from : Int, msg : Bytes) : List(Int) do\n    Msgpack.encode(Msgpack.array(\n      Cons(Msgpack.int(to), Cons(Msgpack.int(from), Cons(Msgpack.bin(Bytes.to_list(msg)), Nil)))))\n  end\n\n  pfn decode_deliver(payload : List(Int)) : Result((Int, Int, Bytes), String) do\n    match decode_deliver_flag(payload) do\n      Ok((to, from, msg, _draining)) -> Ok((to, from, msg))\n      Err(e) -> Err(e)\n    end\n  end\n\n  -- D27: a Deliver sent while the sender's epoch is draining carries a\n  -- fourth element, 1. Only then: a frame from a node that is not draining\n  -- is byte-for-byte the three-element one every older node reads.\n  pfn encode_deliver_flag(to : Int, from : Int, msg : Bytes, draining : Bool) : List(Int) do\n    let head = Cons(Msgpack.int(to), Cons(Msgpack.int(from), Cons(Msgpack.bin(Bytes.to_list(msg)), Nil)))\n    Msgpack.encode(Msgpack.array(if draining do List.append(head, Cons(Msgpack.int(1), Nil)) else head end))\n  end\n\n  pfn decode_deliver_flag(payload : List(Int)) : Result((Int, Int, Bytes, Bool), String) do\n    match Msgpack.decode(payload) do\n      Ok(Msgpack.Array(Cons(Msgpack.Int(to), Cons(Msgpack.Int(from), Cons(Msgpack.Bin(m), rest))))) ->\n        match rest do\n          Nil -> Ok((to, from, Bytes.from_list(m), false))\n          Cons(Msgpack.Int(f), Nil) -> Ok((to, from, Bytes.from_list(m), f == 1))\n          _ -> Err(\"session_node: bad Deliver payload\")\n        end\n      _ -> Err(\"session_node: bad Deliver payload\")\n    end\n  end\n\n  pfn encode_role(role : Int) : List(Int) do Msgpack.encode(Msgpack.int(role)) end\n\n  pfn decode_role(payload : List(Int)) : Result(Int, String) do\n    match Msgpack.decode(payload) do\n      Ok(Msgpack.Int(role)) -> Ok(role)\n      _ -> Err(\"session_node: bad Drained payload\")\n    end\n  end\n\n  -- \u2500\u2500 cluster mode \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- A party run by `run_cluster` has no connections of its own: it rides the\n  -- cluster node's (ClusterNode), shared by every session between the two\n  -- nodes. Its frames carry the session id in the type tag\n  -- (\"SessionNode.Deliver#<sid>\"), so a frame for another session -- an\n  -- old one whose endpoint pid was reused -- is refused, not delivered.\n\n  pfn is_cluster(p : Party) : Bool do Vault.get(p.why, \"sid\") != None end\n\n  pfn wire_tag(p : Party, kind : String) : String do\n    match Vault.get(p.why, \"sid\") do\n      Some(sid) -> kind ++ \"#\" ++ sid\n      None -> kind\n    end\n  end\n\n  -- Bye names its sender in cluster mode (one route serves every peer, so\n  -- the connection no longer says who it is from); empty otherwise, as\n  -- before.\n  pfn bye_payload(p : Party) : List(Int) do\n    if is_cluster(p) do Msgpack.encode(Msgpack.int(p.my_role)) else Nil end\n  end\n\n  pfn next_seq(meta : Vault(Int)) : Int do\n    Vault.incr(meta, \"seq\", 1)\n  end\n\n  -- The seq a frame goes out under: a cluster party's (one with a \"skey\",\n  -- `run_cluster_party`) is a `ClusterNode.session_seq`, so a\n  -- DELIVERY_FAILED for it comes back to this party (`slot_refused`).\n  pfn wire_seq(meta : Vault(Int)) : Int do\n    let n = next_seq(meta)\n    match Vault.get(meta, \"skey\") do\n      Some(k) -> ClusterNode.session_seq(k, n)\n      None -> n\n    end\n  end\n\n  -- \u2500\u2500 delivery: expected sender first, everyone else parked \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn take_pending(pending : Vault(List((Int, Bytes))), ep : Int, want : Int) : Option((Int, Bytes)) do\n    let queued = Vault.get_or(pending, ekey(ep), Nil)\n    let hit = List.find(queued, fn e -> match e do (from, _) -> want == 0 || from == want end)\n    match hit do\n      None -> None\n      Some(found) ->\n        match found do\n          (from, _) ->\n            -- Drop the first entry from that sender: per-peer FIFO is the\n            -- order they were parked in.\n            let rest = drop_first(queued, from, Nil)\n            Vault.set(pending, ekey(ep), rest)\n            Some(found)\n        end\n    end\n  end\n\n  -- Whether anything is parked on [ep] that a continuation awaiting [want]\n  -- (0: anyone) would take.\n  pfn has_pending(pending : Vault(List((Int, Bytes))), ep : Int, want : Int) : Bool do\n    List.any(Vault.get_or(pending, ekey(ep), Nil), fn e -> match e do (from, _) -> want == 0 || from == want end)\n  end\n\n  pfn drop_first(xs : List((Int, Bytes)), from : Int, seen : List((Int, Bytes))) : List((Int, Bytes)) do\n    match xs do\n      Nil -> List.reverse(seen)\n      Cons(e, rest) ->\n        match e do\n          (f, _) -> if f == from do List.append(List.reverse(seen), rest) else drop_first(rest, from, Cons(e, seen)) end\n        end\n    end\n  end\n\n  pfn park(pending : Vault(List((Int, Bytes))), ep : Int, from : Int, msg : Bytes) : () do\n    Vault.set(pending, ekey(ep), List.append(Vault.get_or(pending, ekey(ep), Nil), Cons((from, msg), Nil)))\n  end\n\n  -- \u2500\u2500 cancellation \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn rkey(role : Int) : String do \"r\" ++ int_to_string(role) end\n\n  pfn ep_done(p : Party) : Bool do Vault.get(p.meta, \"done\") != None end\n\n  pfn encode_cancel(role : Int, cause : String) : List(Int) do\n    Msgpack.encode(Msgpack.array(Cons(Msgpack.int(role), Cons(Msgpack.str(cause), Nil))))\n  end\n\n  pfn decode_cancel(payload : List(Int)) : Result((Int, String), String) do\n    match Msgpack.decode(payload) do\n      Ok(Msgpack.Array(Cons(Msgpack.Int(role), Cons(Msgpack.Str(cause), Nil)))) -> Ok((role, cause))\n      _ -> Err(\"session_node: bad Cancel payload\")\n    end\n  end\n\n  -- Send one session frame (Deliver, Bye, Cancel) to [l]'s peer. These are\n  -- never dropped and the sender never waits (`NodeQueue.Unbounded`): the\n  -- frame is queued past the budget if need be and goes out as the peer's\n  -- credit allows. Under `DropNew`, a message over the 4096-byte budget, or\n  -- most of a burst, was refused and the result ignored: a lost Deliver left\n  -- its receiver waiting forever while both nodes kept heartbeating, and a\n  -- lost Bye or Cancel ended the session later with the wrong cause. The\n  -- sender must not block instead: it runs in the endpoint actor's turn (or\n  -- the host actor's), which handles none of its other messages while it\n  -- waits for credit, so a wait on one slow peer would hold up every other\n  -- (and the reader's `LinkEnded`). The queue grows only while the peer is slow,\n  -- and a peer that stays silent is dropped by the heartbeat, whose\n  -- `drop_link` lets the queue go.\n  --\n  -- Bounded all the same: past MARCH_SESSION_QUEUE_MAX_BYTES (default 64 MiB)\n  -- queued and unread for the peer, it has stopped reading (`over_limit`).\n  pfn send_frame(p : Party, l : Link, type_tag : String, payload : List(Int)) : () do\n    if Vault.get(p.meta, \"over\" ++ rkey(l.role)) != None do ()   -- given up on: discard\n    else\n      let limit = queue_limit()\n      if limit > 0 && NodeQueue.depth(l.q) > limit do over_limit(p, l, limit)\n      else\n        -- `Unbounded` never refuses; a dead connection's reader reports it.\n        let _ = NodeQueue.cast(l.q, wire_seq(p.meta), l.peer, wire_tag(p, type_tag), payload, NodeQueue.Unbounded)\n        ()\n      end\n    end\n  end\n\n  pfn queue_limit() : Int do Env.get_int(\"MARCH_SESSION_QUEUE_MAX_BYTES\", 67108864) end\n\n  -- More than [limit] bytes are queued for [l]'s peer and unread: it has\n  -- stopped reading, and it is given up on, once. Standalone, the\n  -- connection is this session's own and is torn down (`drop_link`, as the\n  -- heartbeat does for a silent peer). In cluster mode the connection and\n  -- its queue are the node's, shared with every other session to that\n  -- node, so only this session gives up: the peer is gone for it and its\n  -- frames to that peer are discarded from now on. Cluster sessions have no\n  -- heartbeat (SWIM watches the node, not whether it reads its data), so\n  -- without this a peer node that stopped reading would let the queue grow\n  -- without bound.\n  pfn over_limit(p : Party, l : Link, limit : Int) : () do\n    if Vault.incr(p.meta, \"over\" ++ rkey(l.role), 1) == 1 do\n      let why = \"stopped reading (over \" ++ int_to_string(limit) ++ \" bytes queued)\"\n      if is_cluster(p) do\n        let _ = send(p.ep, PeerGone(p, l.role, why))\n        link_ended(p, l.role, why)\n      else drop_link(p, l, why) end\n    else () end\n  end\n\n  -- Give up on [l]'s peer: report it gone, let its queue go, and shut BOTH\n  -- connections down -- the data one ends the reader, the control one ends\n  -- the control reader, which `finish` awaits and which would otherwise\n  -- wait for a Bye the peer may never send.\n  pfn drop_link(p : Party, l : Link, why : String) : () do\n    send(p.ep, PeerGone(p, l.role, why))\n    NodeQueue.close(l.q)\n    tcp_shutdown(l.data_fd)\n    tcp_shutdown(l.control_fd)\n  end\n\n  -- Kinds of our own endpoint's cancellation, for `run`'s result.\n  pfn kind_cancelled() : Int do 1 end\n  pfn kind_protocol() : Int do 2 end\n  pfn kind_host_gone() : Int do 3 end\n  pfn kind_left() : Int do 4 end\n\n  -- Cancel our endpoint [ep]: record why, run the cancel handler installed\n  -- with the continuation it was waiting in (or tell the hosting actor),\n  -- and send `Cancel(my_role, outward)` on every data connection, behind\n  -- everything this role already sent. [role] is the peer this failure is\n  -- attributed to, [cause] why, [outward] what the peers are told. Runs in\n  -- the endpoint actor's turn (every caller is one of its handlers, or the\n  -- generated handler it is running), and is idempotent: an endpoint that\n  -- already closed or was cancelled is left alone.\n  pfn cancel_endpoint(p : Party, ep : Int, role : Int, cause : String, outward : String, kind : Int) : () do\n    if ep_done(p) do ()\n    else\n      Vault.set(p.meta, \"done\", 1)\n      Vault.set(p.meta, \"kind\", kind)\n      Vault.set(p.meta, \"cancel_role\", role)\n      Vault.set(p.why, \"cancel_cause\", cause)\n      let _ = Vault.delete(p.handlers, ekey(ep))\n      let handler = match Vault.get(p.cancel_hs, ekey(ep)) do\n        Some(h) -> Some(h)\n        None -> Vault.get(p.cancel_hs, \"cur\" ++ ekey(ep))\n      end\n      let _ = Vault.delete(p.cancel_hs, ekey(ep))\n      let _ = Vault.delete(p.cancel_hs, \"cur\" ++ ekey(ep))\n      match handler do\n        Some(h) ->\n          let _ = h(role, cause, ep)\n          ()\n        None -> ()\n      end\n      match Vault.get(p.forward_cancel, \"c\") do\n        Some(f) -> f(role, cause, ep)\n        None -> ()\n      end\n      let _ = List.map(p.links, fn l -> send_frame(p, l, \"SessionNode.Cancel\", encode_cancel(p.my_role, outward)))\n      ()\n    end\n  end\n\n  -- Can [want] (0 = any peer) send us nothing more? `Some((role, why))` if\n  -- so. For 0: every connected peer is gone.\n  pfn blocked_on(p : Party, want : Int) : Option((Int, String)) do\n    if want != 0 do\n      match Vault.get(p.gone, rkey(want)) do\n        Some(why) -> Some((want, why))\n        None -> None\n      end\n    else\n      match p.links do\n        Nil -> None\n        Cons(first, _) ->\n          if List.all(p.links, fn l -> Vault.get(p.gone, rkey(l.role)) != None) do\n            Some((first.role, Vault.get_or(p.gone, rkey(first.role), \"gone\")))\n          else None end\n      end\n    end\n  end\n\n  -- Maty's E-CancelH: our endpoint's continuation waits on a role that can\n  -- send nothing more, and nothing from that role is queued. Called after\n  -- every drain (which consumed anything that WAS queued) and whenever a\n  -- peer goes. A role that closed normally counts too: waiting on it with\n  -- nothing queued means waiting forever.\n  --\n  -- Crash branches (the protocol declared the role `may crash`, and the\n  -- receive installed a crash continuation for it, `Session.on_crash`, which\n  -- an actor-hosted `await_\u2026` does too): the\n  -- continuation waiting on it is replaced by the crash branch, run here as\n  -- a delivery would be -- in the endpoint actor's turn, then `drain` for\n  -- whatever the branch installs next. The endpoint stays live and no Cancel\n  -- frame goes out; messages to the crashed role are discarded by `emit`.\n  -- The `drain` here recurses into `check_waiting` only if the branch's own\n  -- first receive waits on another role that is gone: bounded by the\n  -- protocol's nesting of crash branches, hence the annotation.\n  @[no_warn_recursion]\n  pfn check_waiting(p : Party, ep : Int) : () do\n    if ep_done(p) do ()\n    else\n      match Vault.get(p.handlers, ekey(ep)) do\n        None -> ()\n        Some(_) ->\n          let want = Vault.get_or(p.waiting, ekey(ep), 0)\n          match blocked_on(p, want) do\n            None -> ()\n            Some(found) ->\n              match found do\n                (role, why) ->\n                  if why == \"drained\" do drain_endpoint(p, ep, role) else\n                  let cause = if why == \"closed\" do \"role \" ++ int_to_string(role) ++ \" closed without sending\" else why end\n                  match Vault.get(p.crash_hs, crash_key(ep, role)) do\n                    Some(h) ->\n                      let _ = Vault.delete(p.handlers, ekey(ep))\n                      let _ = Vault.delete(p.crash_hs, crash_key(ep, role))\n                      let _ = Vault.delete(p.cancel_hs, ekey(ep))\n                      match Vault.get(p.forward_crash, \"x\") do\n                        -- Hosted: the actor owns the session state, so it\n                        -- takes the branch, in its own turn, and its next\n                        -- `suspend` drains what is queued (as a delivery\n                        -- does). The continuation installed here is inert.\n                        Some(f) -> f(role, cause, ep)\n                        None ->\n                          let _ = h(role, cause, ep)\n                          let _ = drain(p, ep)\n                          ()\n                      end\n                    None ->\n                      cancel_endpoint(p, ep, role, cause, \"role \" ++ int_to_string(role) ++ \": \" ++ cause, kind_cancelled())\n                  end\n                  end\n              end\n          end\n      end\n    end\n  end\n\n  -- A peer can send nothing more: it closed ([why] = \"closed\") or was\n  -- cancelled. The first report wins; a later one (the reader's end of file\n  -- after a Cancel frame, say) is ignored.\n  pfn peer_gone(p : Party, role : Int, why : String) : () do\n    match Vault.get(p.gone, rkey(role)) do\n      Some(_) -> ()\n      None ->\n        Vault.set(p.gone, rkey(role), why)\n        -- Drained here, and this is the peer's end: nothing more it sends\n        -- needs returning (an Undelivered coming back needs no answer), so\n        -- this side's Bye can go now (see `drain_endpoint`).\n        if Vault.get(p.meta, \"drained\") != None do bye_to(p, role) else () end\n        match Vault.get(p.meta, \"ep\") do\n          Some(ep) -> check_waiting(p, ep)\n          None -> ()\n        end\n    end\n  end\n\n  -- \u2500\u2500 drains (D27, plan 6.2 and II.5.4) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- The rule, for any number of roles (specs/progress/2026-09-24-dd-d27-\n  -- session-drains.md states it and its proof):\n  --   1. A delivery to our endpoint's continuation installed at a loop\n  --      boundary (`suspend_at_boundary`), when our epoch is draining or the\n  --      sender's was when it sent it, is NOT consumed: it goes back to the\n  --      sender as Undelivered, and our endpoint DRAINS.\n  --   2. A drained endpoint returns every message addressed to it that it has\n  --      not consumed: those parked here, and every one that arrives later.\n  --   3. It announces Drained to every peer, behind everything it sent. A\n  --      peer marks the role drained; its messages to that role from then on\n  --      come back at `emit`, without a round trip.\n  --   4. An endpoint whose continuation waits on a drained role, with nothing\n  --      from it queued, drains in turn (rules 2-3 again): a role mid-\n  --      iteration ends at its next receive from a drained role.\n  --   5. A drained endpoint's Bye to a peer waits for that peer's own end\n  --      (Bye, Cancel or Drained), after which nothing it sends needs\n  --      returning; each reader keeps reading to the peer's Bye.\n  -- Our own messages that came back are kept (pending, key \"u\") for the\n  -- drain handler and counted (\"undelivered\") for `run`'s result.\n\n  pfn drained_here(p : Party) : Bool do Vault.get(p.meta, \"drained\") != None end\n\n  pfn is_drained_role(p : Party, role : Int) : Bool do\n    match Vault.get(p.gone, rkey(role)) do\n      Some(w) -> w == \"drained\"\n      None -> false\n    end\n  end\n\n  -- [role] sent a message to our endpoint while its epoch was draining.\n  pfn sender_draining(p : Party, role : Int) : Bool do\n    Vault.get(p.meta, \"sdrain\" ++ rkey(role)) != None\n  end\n\n  -- One of our messages came back undelivered from [role].\n  pfn record_undelivered(p : Party, role : Int, msg : Bytes) : () do\n    park(p.pending, -2, role, msg)\n    let _ = Vault.incr(p.meta, \"undelivered\", 1)\n    ()\n  end\n\n  pfn undelivered_msgs(p : Party) : List(Bytes) do\n    List.map(Vault.get_or(p.pending, ekey(-2), Nil), fn e -> match e do (_r, m) -> m end)\n  end\n\n  -- [msg], from [from], goes back to [from] undelivered.\n  pfn return_to(p : Party, from : Int, msg : Bytes) : () do\n    let _ = Vault.incr(p.meta, \"returned\", 1)\n    send_frame(p, link_for(p.links, from), \"SessionNode.Undelivered\", encode_deliver(from, p.my_role, msg))\n  end\n\n  -- This side's Bye to [role], once.\n  pfn bye_to(p : Party, role : Int) : () do\n    if Vault.incr(p.meta, \"bye\" ++ rkey(role), 1) == 1 do\n      match List.find(p.links, fn l -> l.role == role) do\n        Some(l) -> send_frame(p, l, \"SessionNode.Bye\", bye_payload(p))\n        None -> ()\n      end\n    else () end\n  end\n\n  -- Drain our endpoint [ep]: [role] is the drained role its continuation\n  -- waited on, 0 when it drained at its own boundary. Runs in the endpoint\n  -- actor's turn; idempotent, and a no-op for an endpoint already done.\n  pfn drain_endpoint(p : Party, ep : Int, role : Int) : () do\n    if ep_done(p) do ()\n    else\n      Vault.set(p.meta, \"done\", 1)\n      Vault.set(p.meta, \"drained\", 1)\n      Vault.set(p.meta, \"drained_on\", role)\n      let handler = Vault.get(p.drain_hs, ekey(ep))\n      let _ = Vault.delete(p.handlers, ekey(ep))\n      let _ = Vault.delete(p.drain_hs, ekey(ep))\n      let _ = Vault.delete(p.cancel_hs, ekey(ep))\n      let _ = Vault.delete(p.cancel_hs, \"cur\" ++ ekey(ep))\n      let _ = List.map(p.links, fn l -> Vault.delete(p.crash_hs, crash_key(ep, l.role)))\n      -- Rule 2: what was parked for us goes back, in the order it came.\n      let parked = Vault.get_or(p.pending, ekey(ep), Nil)\n      let _ = Vault.delete(p.pending, ekey(ep))\n      let _ = List.map(parked, fn e -> match e do (from, msg) -> return_to(p, from, msg) end)\n      -- Rule 3, then rule 5 for peers that have already ended.\n      let _ = List.map(p.links, fn l -> send_frame(p, l, \"SessionNode.Drained\", encode_role(p.my_role)))\n      let _ = List.map(p.links, fn l -> if Vault.get(p.gone, rkey(l.role)) != None do bye_to(p, l.role) else () end)\n      match handler do\n        Some(h) ->\n          let _ = h(role, undelivered_msgs(p), ep)\n          ()\n        None -> ()\n      end\n      -- Hosted: the actor holds the parked state; it hears of the drain on\n      -- the cancel route, with the cause \"drained\", and closes its endpoint.\n      match Vault.get(p.forward_cancel, \"c\") do\n        Some(f) -> f(role, \"drained\", ep)\n        None -> ()\n      end\n    end\n  end\n\n  -- Hand a delivery the continuation [k] on [ep] is waiting for to it --\n  -- unless it drains our endpoint (rule 1).\n  pfn consume(p : Party, k : Int -> Bytes -> Int -> Int, ep : Int, from : Int, msg : Bytes) : Int do\n    if Vault.get_or(p.meta, \"boundary\" ++ ekey(ep), 0) == 1\n         && (sender_draining(p, from) || epoch_draining()) do\n      return_to(p, from, msg)\n      drain_endpoint(p, ep, 0)\n      ep\n    else resume_with(p, k, ep, from, msg) end\n  end\n\n  -- The generated code could not deliver a message to [ep]'s continuation\n  -- (`Session.fail`): the peer that sent it is not speaking the protocol.\n  -- That peer is treated as failed: our endpoint is cancelled (with the\n  -- cancel handler of the receive that got the message) and `run` reports\n  -- `Protocol(from, why)`. `from` is the sender of the delivery being\n  -- resumed (recorded by `resume_with`). Runs inside that delivery, in the\n  -- endpoint actor's turn.\n  pfn protocol_failed(p : Party, ep : Int, why : String) : () do\n    let from = Vault.get_or(p.meta, \"from\", 0)\n    Vault.set(p.gone, rkey(from), \"protocol: \" ++ why)\n    cancel_endpoint(p, ep, from, why, \"role \" ++ int_to_string(from) ++ \": protocol: \" ++ why, kind_protocol())\n  end\n\n  -- Watches a hosted party's actor: its `Down` -- a crash, a kill, a\n  -- supervisor's restart -- is the session's end, whether or not a delivery\n  -- was in flight. (Detecting it at the next delivery is not enough: a host\n  -- that dies between resuming and re-parking has no handler installed, so\n  -- the next delivery is parked and nothing would ever look.) `Down` is a\n  -- raw mailbox message, so a dedicated actor reads it with `receive`;\n  -- `run_hosted` sets the monitor (`monitor(watcher, host)`, from outside\n  -- the actor, as the monitor fixture does) and kills the watcher when the\n  -- session ends, so it is not left parked in `receive`.\n  actor HostWatch do\n    state { n : Int }\n    init  { n: 0 }\n    on Watch(p : Party, ep : Int) do\n      -- Only a `Down` ever arrives: the session's end kills this actor\n      -- rather than messaging it (a message would be read here as a\n      -- `Down`, `receive()` being typed by this pattern).\n      match receive() do\n        Down.Down(_, _, reason) ->\n          -- A hot-reload hard drain kills the host with Crash(\"draining\"):\n          -- pass that on, and the Endpoint ends the session as drained.\n          let why = match reason do\n            DownReason.Crash(w) -> w\n            _ -> \"\"\n          end\n          let _ = send(p.ep, HostDown(p, ep, why))\n          ()\n      end\n      { n: state.n + 1 }\n    end\n  end\n\n  -- Hand [msg] to the continuation that awaits on [ep]: the installed handler\n  -- (callback API), or the host actor through `forward` (hosted party), which\n  -- gets ONE delivery per suspension -- it re-suspends when it has resumed,\n  -- and that drains the next.\n  pfn resume_with(p : Party, k : Int -> Bytes -> Int -> Int, ep : Int, from : Int, msg : Bytes) : Int do\n    let _ = Vault.delete(p.handlers, ekey(ep))\n    -- Who this delivery is from, for `fail`: a message the continuation\n    -- cannot take is reported against its sender (RunError.Protocol).\n    Vault.set(p.meta, \"from\", from)\n    -- The cancel handler belongs to the continuation just consumed. It\n    -- stays reachable (\"cur\") while that continuation runs, because `fail`\n    -- inside it cancels with THIS receive's handler; the next suspend\n    -- installs its own.\n    match Vault.get(p.cancel_hs, ekey(ep)) do\n      Some(h) ->\n        Vault.set(p.cancel_hs, \"cur\" ++ ekey(ep), h)\n        let _ = Vault.delete(p.cancel_hs, ekey(ep))\n        ()\n      None -> ()\n    end\n    -- So does the crash continuation: the message arrived, so the sender\n    -- did not crash before sending it.\n    let _ = Vault.delete(p.crash_hs, crash_key(ep, from))\n    match Vault.get(p.forward, \"f\") do\n      None ->\n        let _ = k(from, msg, ep)\n        let _ = Vault.delete(p.cancel_hs, \"cur\" ++ ekey(ep))\n        drain(p, ep)\n      Some(f) ->\n        f(from, msg, ep)\n        let _ = Vault.delete(p.cancel_hs, \"cur\" ++ ekey(ep))\n        ep\n    end\n  end\n\n  doc \"\"\"\n  Deliver [msg] from role [from] to local endpoint [ep]: run the\n  continuation installed on [ep] with it, then drain whatever parked\n  messages the new continuation is now willing to take. Returns [ep].\n\n  A delivery nobody expects yet (no continuation installed, the installed\n  one waits on a different role, or an older message from the same sender is\n  still parked) is parked, not dropped. If [ep] has already closed or been\n  cancelled the message is discarded, except on a drained endpoint, where it\n  goes back to its sender. Normally called from the party's endpoint actor\n  when a \"SessionNode.Deliver\" frame arrives; it must run in that actor's\n  turn.\n  \"\"\"\n  fn deliver(p : Party, ep : Int, from : Int, msg : Bytes) : Int do\n    let want = Vault.get_or(p.waiting, ekey(ep), 0)\n    if ep_done(p) do\n      -- Our endpoint closed or was cancelled: discard. Drained: the message\n      -- goes back to its sender (D27 rule 2), so none is silently lost.\n      if drained_here(p) do return_to(p, from, msg) else () end\n      ep\n    else\n    match Vault.get(p.handlers, ekey(ep)) do\n      None ->\n        park(p.pending, ep, from, msg)\n        ep\n      Some(k) ->\n        if want == 0 || want == from do\n          -- Per-sender FIFO: an older message parked from a sender this\n          -- continuation takes goes first. In the callback API the drain\n          -- runs in this same turn as the install, so nothing is ever\n          -- parked here; a HOSTED endpoint's `suspend` installs in the host's\n          -- turn and only queues a `Drain`, and a delivery handled before\n          -- that Drain overtook the parked one: the host, awaiting the first\n          -- message, was resumed with the second (\"unexpected message in\n          -- state ...\", specs/progress/2026-10-05-hosted-protocol-change-\n          -- unexpected-hello-under-asan.md).\n          if has_pending(p.pending, ep, want) do\n            park(p.pending, ep, from, msg)\n            drain(p, ep)\n          else\n            -- This continuation is consumed by the call; anything parked is\n            -- for whatever it installs next.\n            consume(p, k, ep, from, msg)\n          end\n        else\n          park(p.pending, ep, from, msg)\n          ep\n        end\n    end\n    end\n  end\n\n  -- `check_waiting` below may run a crash branch and drain again: the\n  -- recursion is bounded by the protocol's nesting of crash branches.\n  @[no_warn_recursion]\n  pfn drain(p : Party, ep : Int) : Int do\n    let want = Vault.get_or(p.waiting, ekey(ep), 0)\n    match Vault.get(p.handlers, ekey(ep)) do\n      None -> ep\n      Some(k) ->\n        match take_pending(p.pending, ep, want) do\n          None ->\n            -- Nothing queued from the role this continuation wants: if that\n            -- role can send nothing more, this is where we fail.\n            check_waiting(p, ep)\n            ep\n          Some(entry) ->\n            match entry do\n              (from, msg) -> consume(p, k, ep, from, msg)\n            end\n        end\n    end\n  end\n\n  -- The endpoint actor: a delivery's continuation runs in its turn. It also\n  -- collects the readers' outcomes for `serve` (`Expect` the link count,\n  -- then one `LinkEnded` per reader) and answers `AwaitOutcome` at the FIRST\n  -- failure or the last clean end, whichever comes first -- so a party whose\n  -- peer died is not stuck awaiting readers parked on peers still alive.\n  -- `failed` is empty for a clean end, else `(role, why)` per failed reader.\n  pfn settled(st : EndpointState) : Bool do\n    st.links > 0 && st.ended >= st.links\n  end\n\n  pfn ep_state(n : Int, links : Int, ended : Int, failed : List((Int, String)),\n               waiters : List(List((Int, String)) -> Unit)) : EndpointState do\n    { n: n, links: links, ended: ended, failed: failed, waiters: waiters }\n  end\n\n  -- Handler ORDER is load-bearing: `Actor.call` routes a sentinel to the\n  -- handler at the sentinel's constructor index within its own type\n  -- (`EndpointReq`: `DeliverReq` = 0, `OutcomeReq` = 1), as in NodeQueue.\n  actor Endpoint do\n    state { n : Int, links : Int, ended : Int, failed : List((Int, String)),\n            waiters : List(List((Int, String)) -> Unit) }\n    init  { n: 0, links: 0, ended: 0, failed: Nil, waiters: Nil }\n    on Deliver(p : Party, ep : Int, from : Int, msg : Bytes) do\n      let _ = deliver(p, ep, from, msg)\n      ep_state(state.n + 1, state.links, state.ended, state.failed, state.waiters)\n    end\n    on AwaitOutcome(reply_to) do\n      if settled(state) do\n        Actor.reply(reply_to, state.failed)\n        state\n      else\n        -- Held across turns: retained, and as the closure that answers it\n        -- (an Int-typed slot would tag the ref; see NodeQueue.Wait). Only\n        -- the newest: the one asker (`await_outcome`) asks again every\n        -- second, and an older ask has already timed out.\n        let r = actor_reply_retain(reply_to)\n        ep_state(state.n, state.links, state.ended, state.failed,\n                 Cons(fn out -> Actor.reply(r, out), Nil))\n      end\n    end\n    on Expect(links : Int) do\n      ep_state(state.n, links, state.ended, state.failed, state.waiters)\n    end\n    on LinkEnded(role : Int, why : String) do\n      let failed = if why == \"\" do state.failed else List.append(state.failed, Cons((role, why), Nil)) end\n      let st = ep_state(state.n, state.links, state.ended + 1, failed, state.waiters)\n      if settled(st) do\n        let _ = List.map(st.waiters, fn w -> w(st.failed))\n        ep_state(st.n, st.links, st.ended, st.failed, Nil)\n      else\n        st\n      end\n    end\n    -- A hosted party's `suspend` runs in the HOST actor's turn; the drain of\n    -- what was parked meanwhile runs here, in this actor's turn, so every\n    -- look-then-act on `handlers`/`pending` happens in one mailbox order.\n    on Drain(p : Party, ep : Int) do\n      let _ = drain(p, ep)\n      state\n    end\n    -- A peer can send nothing more. Queued behind every delivery from it.\n    on PeerGone(p : Party, role : Int, why : String) do\n      peer_gone(p, role, why)\n      state\n    end\n    -- The hosting actor died: our endpoint's session state died with it.\n    on HostDown(p : Party, ep : Int, why : String) do\n      -- A hot-reload hard drain deadline killed the host (II.4.7): the\n      -- session ends as `Left(\"draining\")`, not as a crash.\n      if why == \"draining\" do\n        cancel_endpoint(p, ep, p.my_role, \"draining\", \"draining\", kind_left())\n      else\n        cancel_endpoint(p, ep, p.my_role, \"host gone\", \"host gone\", kind_host_gone())\n      end\n      state\n    end\n    -- Hot reload (DD step 6, plan II.4.4, D28): this actor runs the party's\n    -- session callbacks, so it holds the session's epoch -- the code version\n    -- the session formed under -- from its spawn (`party`) until `finish`\n    -- sends this.  Handled in this actor's own turn, where the hold is.\n    -- Appended after every other handler: `Actor.call` addresses the first\n    -- two by position (see the note above the actor).\n    on ReleaseEpoch() do\n      epoch_release()\n      state\n    end\n\n    -- `Session.leave`: this role exits the session on purpose.\n    on Leave(p : Party, ep : Int, why : String) do\n      cancel_endpoint(p, ep, p.my_role, \"left: \" ++ why, \"left: \" ++ why, kind_left())\n      state\n    end\n    -- Cluster mode: a frame that arrived before this session was ready\n    -- (its peers found, its party complete). Held here, in this actor's\n    -- mailbox order, rather than by the node's data reader, which every\n    -- other session and route on that connection shares; replayed on\n    -- `Ready`. A frame after `Ready` is handled at once.\n    on Early(slot : Vault(Party), p0 : Party, kind : Int, payload : Bytes) do\n      match Vault.get(slot, \"p\") do\n        Some(p) ->\n          if Vault.get(p.meta, \"ready\") != None do\n            let _ = cluster_kind_here(p, early_kind_name(kind), Bytes.to_list(payload))\n            ()\n          else park(p0.pending, -1, kind, payload) end\n        None -> park(p0.pending, -1, kind, payload)\n      end\n      state\n    end\n    on Ready(p : Party) do\n      Vault.set(p.meta, \"ready\", 1)\n      let held = Vault.get_or(p.pending, ekey(-1), Nil)\n      let _ = Vault.delete(p.pending, ekey(-1))\n      let _ = List.map(held, fn e -> match e do\n        (kind, payload) -> cluster_kind_here(p, early_kind_name(kind), Bytes.to_list(payload))\n      end)\n      state\n    end\n    -- D27: a delivery its sender sent while its epoch was draining.\n    on DeliverDraining(p : Party, ep : Int, from : Int, msg : Bytes) do\n      Vault.set(p.meta, \"sdrain\" ++ rkey(from), 1)\n      let _ = deliver(p, ep, from, msg)\n      ep_state(state.n + 1, state.links, state.ended, state.failed, state.waiters)\n    end\n    -- D27: one of our messages came back from [role], which drained.\n    on Returned(p : Party, role : Int, msg : Bytes) do\n      record_undelivered(p, role, msg)\n      peer_gone(p, role, \"drained\")\n      state\n    end\n  end\n\n  type EndpointReq = DeliverReq | OutcomeReq\n\n  -- \u2500\u2500 hello: role + endpoint pid \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- The protocol fingerprint rides the hello as an OPTIONAL THIRD element\n  -- (2026-09-21). A node built before this sends the two-element hello it\n  -- always sent, and a node built after can still read it -- otherwise an\n  -- old and a new node would deadlock at the handshake instead of reporting\n  -- the skew. `\"\"` means \"nothing to say\": the raw party API\n  -- (`accept_from` / `connect_to` / `open`) has no protocol identity of its\n  -- own, so it neither sends nor demands one. See `hello_verdict`.\n  pfn encode_hello(role : Int, me : GlobalPid.Pid, fingerprint : String) : List(Int) do\n    let head = Cons(Msgpack.int(role), Cons(Msgpack.bin(GlobalPid.encode(me)), Nil))\n    Msgpack.encode(Msgpack.array(\n      if fingerprint == \"\" do head\n      else List.append(head, Cons(Msgpack.str(fingerprint), Nil)) end))\n  end\n\n  pfn decode_hello(payload : List(Int)) : Result((Int, GlobalPid.Pid, String), String) do\n    match Msgpack.decode(payload) do\n      Ok(Msgpack.Array(Cons(Msgpack.Int(role), Cons(Msgpack.Bin(pid_bytes), rest)))) ->\n        let fp = match rest do\n          Cons(Msgpack.Str(s), Nil) -> s\n          _ -> \"\"\n        end\n        match GlobalPid.decode(pid_bytes) do\n          Ok(pid) -> Ok((role, pid, fp))\n          Err(e) -> Err(\"session_node: hello pid: \" ++ e)\n        end\n      _ -> Err(\"session_node: bad Hello payload\")\n    end\n  end\n\n  doc \"\"\"\n  Whether a peer that announced [theirs] may join a session this node runs\n  under the protocol fingerprint [mine] (`<P>_Msg.fingerprint()`).\n\n  [mine] is `\"\"` when this side has no protocol identity to compare (the raw\n  party API), and then anything is accepted -- that path never had a check.\n  [theirs] is `\"\"` when the peer sent a hello with no fingerprint in it,\n  which since 2026-09-21 means the peer is older than the check itself; that\n  is a REFUSAL with a clear reason, not a silent accept. The `Handshake:`\n  prefix is the one `dial_retry` stops on, so a skew is reported at once\n  instead of retried until the connect budget runs out.\n  \"\"\"\n  pfn hello_verdict(mine : String, theirs : String) : Result((), String) do\n    if mine == \"\" do Ok(())\n    else if theirs == \"\" do\n      Err(\"Handshake: the peer sent no protocol fingerprint, so it was built before the session \"\n          ++ \"handshake carried one; the two sides cannot be shown to run the same protocol. \"\n          ++ \"Rebuild both from the same source.\")\n    else if mine != theirs do\n      Err(\"Handshake: this node and its peer were built from DIFFERENT versions of the protocol \"\n          ++ \"(fingerprint \" ++ mine ++ \" here, \" ++ theirs ++ \" there). Rebuild both from the \"\n          ++ \"same source.\")\n    else Ok(()) end end end\n  end\n\n  pfn announce(fd : Int, role : Int, me : GlobalPid.Pid, fingerprint : String) : () do\n    let _ = NodeSend.cast(fd, 0, GlobalPid.make(\"peer\", 0, 0), \"SessionNode.Hello\",\n                          encode_hello(role, me, fingerprint))\n    ()\n  end\n\n  pfn read_hello(fd : Int) : Result((Int, GlobalPid.Pid, String), String) do\n    match NetKernel.recv_frame_exact(fd) do\n      Err(e) -> Err(\"session_node: hello: \" ++ e)\n      Ok(frame) ->\n        match NodeSend.decode_msg(frame) do\n          Ok(d) ->\n            if d.type_tag != \"SessionNode.Hello\" do Err(\"session_node: expected a Hello, got \" ++ d.type_tag)\n            else decode_hello(d.payload) end\n          Err(e) -> Err(\"session_node: hello frame: \" ++ e)\n        end\n    end\n  end\n\n  pfn await_hello(fd : Int) : (Int, GlobalPid.Pid, String) do\n    match read_hello(fd) do\n      Ok(hello) -> hello\n      Err(e) -> panic(e)\n    end\n  end\n\n  -- `read_hello` bounded by [timeout_ms] (> 0): the control socket's receive\n  -- timeout covers the read and is cleared again before the control reader\n  -- takes the socket over.\n  pfn read_hello_within(fd : Int, timeout_ms : Int) : Result((Int, GlobalPid.Pid, String), String) do\n    let _ = if timeout_ms > 0 do tcp_set_recv_timeout(fd, timeout_ms) else Ok(()) end\n    let r = read_hello(fd)\n    let _ = if timeout_ms > 0 do tcp_set_recv_timeout(fd, 0) else Ok(()) end\n    r\n  end\n\n  -- \u2500\u2500 control connection \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- CREDIT feeds the queue; a Bye ends it (each side awaits its own reader, so\n  -- closing first and awaiting would deadlock).\n  pfn on_control(q : (Pid(NodeQueue.WriterState), Int), tag : Int, frame : List(Int)) : Result(Bool, String) do\n    if tag == NodeQueue.tag_credit() do\n      match NodeQueue.decode_credit(frame) do\n        Ok(total) ->\n          NodeQueue.credit(q, total)\n          Ok(true)\n        Err(e) -> Err(e)\n      end\n    else\n      if tag == NodeSend.tag_actor_msg() do\n        match NodeSend.decode_msg(frame) do\n          Ok(d) -> Ok(d.type_tag != \"SessionNode.Bye\")\n          Err(e) -> Err(e)\n        end\n      else\n        if tag == NodeSend.tag_delivery_failed() do\n          match NodeSend.decode_failed(frame) do\n            Ok((seq, reason)) -> Err(\"session_node: delivery \" ++ int_to_string(seq) ++ \" failed: \" ++ reason)\n            Err(e) -> Err(e)\n          end\n        else\n          Err(\"session_node: unexpected tag \" ++ int_to_string(tag) ++ \" on the control connection\")\n        end\n      end\n    end\n  end\n\n  pfn serve_control(control_fd : Int, q : (Pid(NodeQueue.WriterState), Int)) : Int do\n    match PeerReader.serve(control_fd, Nil, fn (tag, frame) -> on_control(q, tag, frame)) do\n      Ok(_) -> 0\n      Err(_) -> 0\n    end\n  end\n\n  -- \u2500\u2500 building a party \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  Start a session on this node in role [my_role] (`<P>_Msg.role_<R>()`), with\n  no peers yet: add one per remote role with `accept_from` / `connect_to`.\n  [on_close] runs when a local endpoint closes, with its endpoint id.\n  \"\"\"\n  fn party(my_role : Int, node_id : String, on_close : Int -> Unit) : Party do\n    -- The Endpoint inherits this proc's code epoch at spawn and holds it\n    -- from the spawn itself until `finish` (hot reload's nesting rule, D28).\n    -- The hold is part of the spawn, not a first message: a message would\n    -- queue behind the epoch marker a spawn from an old-epoch unit gets, and\n    -- the Endpoint would advance before holding.\n    epoch_hold_next_spawn()\n    let ep = spawn(Endpoint)\n    let tag = node_id ++ \".\" ++ int_to_string(my_role) ++ \".\" ++ int_to_string(pid_to_int(ep))\n    let p = { my_role: my_role, node_id: node_id,\n      handlers: Vault.new(\"session_node_handlers_\" ++ tag),\n      waiting: Vault.new(\"session_node_waiting_\" ++ tag),\n      pending: Vault.new(\"session_node_pending_\" ++ tag),\n      meta: Vault.new(\"session_node_meta_\" ++ tag),\n      forward: Vault.new(\"session_node_forward_\" ++ tag),\n      why: Vault.new(\"session_node_why_\" ++ tag),\n      gone: Vault.new(\"session_node_gone_\" ++ tag),\n      cancel_hs: Vault.new(\"session_node_cancel_\" ++ tag),\n      crash_hs: Vault.new(\"session_node_crash_\" ++ tag),\n      forward_cancel: Vault.new(\"session_node_fwdcancel_\" ++ tag),\n      forward_crash: Vault.new(\"session_node_fwdcrash_\" ++ tag),\n      heard: Vault.new(\"session_node_heard_\" ++ tag),\n      drain_hs: Vault.new(\"session_node_drain_\" ++ tag),\n      ep: ep, links: Nil, on_close: on_close }\n    -- Present until the party's tables are closed (`close_party`): a task\n    -- that outlives the session (a heartbeat) stops on its absence.\n    Vault.set(p.meta, \"open\", 1)\n    p\n  end\n\n  -- The session is over and its outcome read: retire the party's thirteen\n  -- tables. Until 2026-10-02 nothing did, and every session left them\n  -- registered, contents and all, for the life of the process -- about\n  -- 300 KB a session; a node forming one every 200 ms grew 1.5 MB/s\n  -- (specs/progress/2026-10-01-session-node-vault-tables-leak.md). Every\n  -- runner exit passes here, after `end_party`, once nothing it waits for\n  -- reads them. A task still holding the party afterwards (a heartbeat\n  -- between two ticks, a reader the shutdown has not woken yet) finds them\n  -- empty: no \"open\", no \"done\"; the heartbeat stops on the first, and the\n  -- tables themselves are freed with the last handle.\n  pfn close_party(p : Party) : () do\n    Vault.close(p.handlers)\n    Vault.close(p.waiting)\n    Vault.close(p.pending)\n    Vault.close(p.meta)\n    Vault.close(p.forward)\n    Vault.close(p.why)\n    Vault.close(p.gone)\n    Vault.close(p.cancel_hs)\n    Vault.close(p.crash_hs)\n    Vault.close(p.forward_cancel)\n    Vault.close(p.forward_crash)\n    Vault.close(p.heard)\n    Vault.close(p.drain_hs)\n  end\n\n  pfn with_link(p : Party, l : Link) : Party do\n    { my_role: p.my_role, node_id: p.node_id, handlers: p.handlers, waiting: p.waiting,\n      pending: p.pending, meta: p.meta, forward: p.forward, why: p.why, gone: p.gone,\n      cancel_hs: p.cancel_hs, crash_hs: p.crash_hs, forward_cancel: p.forward_cancel,\n      forward_crash: p.forward_crash, heard: p.heard, drain_hs: p.drain_hs, ep: p.ep,\n      links: List.append(p.links, Cons(l, Nil)), on_close: p.on_close }\n  end\n\n  -- The heartbeat starts with the connection, not with `serve`: a role\n  -- that works past the timeout before its first send or receive (driving\n  -- to its first suspension runs before `serve`) is pinging its peers all\n  -- the while, so it is not taken for dead. See `heartbeat`.\n  pfn start_link(p : Party, their_role : Int, conn : Peer, peer_pid : GlobalPid.Pid) : Party do\n    let q = NodeQueue.start(conn.data_fd, budget())\n    let control = task_spawn(fn _ -> serve_control(conn.fd, q))\n    let l = { role: their_role, data_fd: conn.data_fd, control_fd: conn.fd,\n              peer: peer_pid, q: q, control: control }\n    match heartbeat_config() do\n      (interval, limit) ->\n        if interval > 0 do\n          let _ = task_spawn(fn _ -> heartbeat(p, l, interval, limit))\n          ()\n        else () end\n    end\n    with_link(p, l)\n  end\n\n  doc \"\"\"\n  Add the peer on a connection this node ACCEPTED. The accepting side\n  announces first, then learns the peer's role from its hello -- a listener\n  does not know which role connects next.\n  \"\"\"\n  fn accept_from(p : Party, conn : Peer) : Party do\n    announce(conn.fd, p.my_role, GlobalPid.make(p.node_id, pid_to_int(p.ep), 1), \"\")\n    match await_hello(conn.fd) do\n      (their_role, peer_pid, _fp) -> start_link(p, their_role, conn, peer_pid)\n    end\n  end\n\n  doc \"\"\"\n  Add the peer in role [their_role] on a connection this node OPENED. The\n  peer announces first; a role in its hello that is not [their_role] is a\n  wiring mistake and fails loudly.\n  \"\"\"\n  fn connect_to(p : Party, their_role : Int, conn : Peer) : Party do\n    match await_hello(conn.fd) do\n      (announced, peer_pid, _fp) ->\n        if announced != their_role && announced != 0 && their_role != 0 do\n          panic(\"session_node: connected to role \" ++ int_to_string(their_role) ++ \" but it announced role \" ++ int_to_string(announced))\n        else () end\n        announce(conn.fd, p.my_role, GlobalPid.make(p.node_id, pid_to_int(p.ep), 1), \"\")\n        start_link(p, their_role, conn, peer_pid)\n    end\n  end\n\n  doc \"\"\"\n  The two-party case in one call: a party of one peer over [conn], with role\n  numbers left at 0 (a single-peer party routes every message to its one\n  connection). [accepted] says which side of the connection this is.\n  \"\"\"\n  fn open(conn : Peer, node_id : String, accepted : Bool, on_close : Int -> Unit) : Party do\n    let p = party(0, node_id, on_close)\n    if accepted do accept_from(p, conn) else connect_to(p, 0, conn) end\n  end\n\n  -- The role runner's joins: `accept_from` / `connect_to` with the hello\n  -- bounded by [timeout_ms] and an `Err` instead of a panic when the peer\n  -- goes quiet or sends something else, so `run` can report it. A role that\n  -- announces the wrong number is still a wiring mistake and panics. The\n  -- connection is closed on `Err`.\n  pfn join_accepted(p : Party, conn : Peer, timeout_ms : Int, fingerprint : String) : Result(Party, String) do\n    announce(conn.fd, p.my_role, GlobalPid.make(p.node_id, pid_to_int(p.ep), 1), fingerprint)\n    match read_hello_within(conn.fd, timeout_ms) do\n      Err(e) ->\n        close_peer(conn)\n        Err(e)\n      Ok((their_role, peer_pid, their_fp)) ->\n        match hello_verdict(fingerprint, their_fp) do\n          Err(e) ->\n            close_peer(conn)\n            Err(e)\n          Ok(_) -> Ok(start_link(p, their_role, conn, peer_pid))\n        end\n    end\n  end\n\n  pfn join_dialed(p : Party, their_role : Int, conn : Peer, timeout_ms : Int, fingerprint : String) : Result(Party, String) do\n    match read_hello_within(conn.fd, timeout_ms) do\n      Err(e) ->\n        close_peer(conn)\n        Err(e)\n      Ok((announced, peer_pid, their_fp)) ->\n        if announced != their_role && announced != 0 && their_role != 0 do\n          panic(\"session_node: connected to role \" ++ int_to_string(their_role) ++ \" but it announced role \" ++ int_to_string(announced))\n        else () end\n        -- Announce BEFORE refusing: the peer is parked in its own\n        -- `read_hello_within` and would otherwise wait out its whole\n        -- timeout, reporting a quiet peer rather than the skew both sides\n        -- can see from the two fingerprints.\n        announce(conn.fd, p.my_role, GlobalPid.make(p.node_id, pid_to_int(p.ep), 1), fingerprint)\n        match hello_verdict(fingerprint, their_fp) do\n          Err(e) ->\n            close_peer(conn)\n            Err(e)\n          Ok(_) -> Ok(start_link(p, their_role, conn, peer_pid))\n        end\n    end\n  end\n\n  pfn close_peer(conn : Peer) : () do\n    tcp_close(conn.fd)\n    tcp_close(conn.data_fd)\n  end\n\n  -- Setup failed: tear down every connection made so far, so each peer's\n  -- side sees it end now (and fails its own setup, or is cancelled) rather\n  -- than waiting out its own timeout. Shutdown before close: it wakes the\n  -- control reader parked on the socket, which close alone may not.\n  pfn abort_links(p : Party) : () do\n    let _ = List.map(p.links, fn l -> do\n      -- Stops its heartbeat, which started with the connection.\n      Vault.set(p.meta, \"link_done\" ++ rkey(l.role), 1)\n      NodeQueue.close(l.q)\n      tcp_shutdown(l.data_fd)\n      tcp_shutdown(l.control_fd)\n      let _ = task_await(l.control)\n      tcp_close(l.data_fd)\n      tcp_close(l.control_fd)\n      0\n    end)\n    ()\n  end\n\n  -- \u2500\u2500 routing \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn has_link(links : List(Link), role : Int) : Bool do\n    match List.find(links, fn l -> l.role == role) do\n      Some(_) -> true\n      None -> false\n    end\n  end\n\n  pfn show_roles(rs : List(Int)) : String do\n    String.join(List.map(rs, fn r -> int_to_string(r)), \", \")\n  end\n\n  doc \"\"\"\n  Check that [p] has a connection to every role in [peers] -- the generated\n  `<P>_Msg.peers_<R>()`, every role [R] exchanges a message with -- and panic\n  naming the missing ones. Call it before `serve`, so a wiring mistake fails\n  at startup rather than at the first `emit` to an unreachable role. A party\n  with exactly one peer passes: it routes everything to that connection\n  whatever the role numbers say (the two-party case, where `open` never asked\n  for them).\n  \"\"\"\n  fn require(p : Party, peers : List(Int)) : Party do\n    match p.links do\n      Cons(_, Nil) -> p\n      _ ->\n        let missing = List.filter(peers, fn r -> has_link(p.links, r) == false)\n        match missing do\n          Nil -> p\n          _ -> panic(\"session_node: role \" ++ int_to_string(p.my_role) ++ \" has no connection to role(s) \" ++ show_roles(missing))\n        end\n    end\n  end\n\n  -- The connection that reaches role [to]. A party with exactly ONE peer\n  -- routes everything to it, whatever the role numbers say: that is the\n  -- two-party case, where `open` never asked for role numbers at all.\n  pfn link_for(links : List(Link), to : Int) : Link do\n    match links do\n      Cons(single, Nil) -> single\n      _ ->\n        match List.find(links, fn l -> l.role == to) do\n          Some(l) -> l\n          None -> panic(\"session_node: no connection to role \" ++ int_to_string(to) ++ \" in this party\")\n        end\n    end\n  end\n\n  doc \"The `Session.Ops` for [p]: hand it to `Session.attach`.\"\n  fn ops(p : Party) : Session.Ops do\n    let links = p.links\n    let meta = p.meta\n    let handlers = p.handlers\n    let waiting = p.waiting\n    let on_close = p.on_close\n    let forward = p.forward\n    let ep_actor = p.ep\n    let party = p\n    {\n      register: fn (_ap, role) -> do\n        Vault.set(meta, \"ep\", role)\n        -- Hosted (this runs in the HOST actor's turn, from its start\n        -- handler): the host holds the session's epoch from here until\n        -- `close`, whichever hosting pattern it uses (review finding\n        -- 2026-09-24-dd-review-hosted-register-path-takes-no-hold: the\n        -- generated take_idle held only on the single-session path).\n        match Vault.get(forward, \"f\") do\n          None -> ()\n          Some(_) -> epoch_hold()\n        end\n        role\n      end,\n      emit: fn (ep, to, msg) -> do\n        -- D27: a message to a drained role comes straight back undelivered.\n        if Vault.get(meta, \"done\") == None && is_drained_role(party, to) do\n          record_undelivered(party, to, msg)\n          ep\n        -- Maty's E-CancelMsg: a message to a role that can take no more, or\n        -- from an endpoint that is itself done, is discarded.\n        else if Vault.get(meta, \"done\") != None || Vault.get(party.gone, rkey(to)) != None do\n          let _ = Vault.incr(meta, \"discarded\", 1)\n          ep\n        else\n          send_frame(party, link_for(links, to), \"SessionNode.Deliver\", encode_deliver_flag(to, ep, msg, epoch_draining()))\n          ep\n        end end\n      end,\n      suspend: fn (ep, from, handler) -> do\n        Vault.set(waiting, ekey(ep), from)\n        Vault.set(handlers, ekey(ep), handler)\n        Vault.set(meta, \"boundary\" ++ ekey(ep), 0)\n        -- Hosted: this runs in the host actor's turn. A delivery parked\n        -- while the host was resuming is drained in the endpoint actor's\n        -- turn, never here (see `Drain`).\n        match Vault.get(forward, \"f\") do\n          None -> ()\n          Some(_) ->\n            let _ = send(ep_actor, Drain(party, ep))\n            ()\n        end\n        ep\n      end,\n      close: fn ep -> do\n        on_close(ep)\n        Vault.set(meta, \"closed\", 1)\n        -- Every peer's reader has to learn this endpoint is done. Queued\n        -- BEFORE \"done\" is set: a hosted endpoint closes in the host\n        -- actor's turn while the runner, once every peer has ended, tears\n        -- the party down as soon as it sees \"done\" (`await_hosted_end`);\n        -- a Bye queued after that went out without its session id (the\n        -- tables were closed) and was refused, and the peers waited on it\n        -- for ever.\n        let _ = List.map(links, fn l -> send_frame(party, l, \"SessionNode.Bye\", bye_payload(party)))\n        Vault.set(meta, \"done\", 1)\n        -- Hosted: `finish` runs this in the host's turn; release its hold.\n        -- (A cancelled hosted endpoint releases in the generated `cancel`.)\n        match Vault.get(forward, \"f\") do\n          None -> ()\n          Some(_) -> epoch_release()\n        end\n        ()\n      end,\n      fail: fn (ep, why) -> protocol_failed(party, ep, why),\n      on_cancel: fn (ep, h) -> do\n        Vault.set(party.cancel_hs, ekey(ep), h)\n        ep\n      end,\n      leave: fn (ep, why) -> do\n        let _ = send(ep_actor, Leave(party, ep, why))\n        ()\n      end,\n      on_crash: fn (ep, role, h) -> do\n        Vault.set(party.crash_hs, crash_key(ep, role), h)\n        ep\n      end,\n      suspend_at_boundary: fn (ep, from, handler) -> do\n        Vault.set(waiting, ekey(ep), from)\n        Vault.set(handlers, ekey(ep), handler)\n        Vault.set(meta, \"boundary\" ++ ekey(ep), 1)\n        match Vault.get(forward, \"f\") do\n          None -> ()\n          Some(_) ->\n            let _ = send(ep_actor, Drain(party, ep))\n            ()\n        end\n        ep\n      end,\n      on_drain: fn (ep, h) -> do\n        Vault.set(party.drain_hs, ekey(ep), h)\n        ep\n      end\n    }\n  end\n\n  -- \u2500\u2500 reading \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- Every frame on a data connection is proof of life (the heartbeat's\n  -- counter restarts), and every one is sent to the endpoint actor in the\n  -- order read, so a peer's Bye or Cancel lands behind its deliveries.\n  pfn on_frame(p : Party, l : Link, tag : Int, frame : List(Int)) : Result(Bool, String) do\n    Vault.set(p.heard, rkey(l.role), 0)\n    if tag == NodeSend.tag_actor_msg() do\n      match NodeSend.decode_msg(frame) do\n        Err(e) -> Err(e)\n        Ok(d) ->\n          let _ = NodeQueue.consumed(l.control_fd, budget(), List.length(frame) + 4)\n          if d.type_tag == \"SessionNode.Bye\" do\n            send(p.ep, PeerGone(p, l.role, \"closed\"))\n            Ok(false)\n          else\n            if d.type_tag == \"SessionNode.Cancel\" do\n              match decode_cancel(d.payload) do\n                Ok((role, cause)) ->\n                  send(p.ep, PeerGone(p, role, cause))\n                  Ok(false)\n                Err(e) -> Err(e)\n              end\n            else\n              if d.type_tag == \"SessionNode.Ping\" do\n                Ok(true)\n              else\n                if d.type_tag == \"SessionNode.Deliver\" do\n                  match decode_deliver_flag(d.payload) do\n                    Err(e) -> Err(e)\n                    Ok((to, from, msg, draining)) ->\n                      if draining do send(p.ep, DeliverDraining(p, to, from, msg))\n                      else send(p.ep, Deliver(p, to, from, msg)) end\n                      Ok(true)\n                  end\n                else if d.type_tag == \"SessionNode.Undelivered\" do\n                  match decode_deliver(d.payload) do\n                    Err(e) -> Err(e)\n                    Ok((_to, from, msg)) ->\n                      send(p.ep, Returned(p, from, msg))\n                      Ok(true)\n                  end\n                else if d.type_tag == \"SessionNode.Drained\" do\n                  -- The peer drained; its Bye ends this reader (rule 5).\n                  match decode_role(d.payload) do\n                    Err(e) -> Err(e)\n                    Ok(role) ->\n                      send(p.ep, PeerGone(p, role, \"drained\"))\n                      Ok(true)\n                  end\n                else\n                  Err(\"session_node: unexpected type \" ++ d.type_tag)\n                end end end\n              end\n            end\n          end\n      end\n    else\n      Err(\"session_node: unexpected tag \" ++ int_to_string(tag) ++ \" on the data connection\")\n    end\n  end\n\n  -- Read one peer to its end: its Bye, its Cancel, or the connection\n  -- ending. The last counts as that peer's cancellation at this point in\n  -- the stream (\"connection lost\"); if a Bye or Cancel already arrived, the\n  -- endpoint actor ignores the repeat. \"\" or why the reader stopped.\n  pfn read_link(p : Party, l : Link) : String do\n    match PeerReader.serve(l.data_fd, Nil, fn (tag, frame) -> on_frame(p, l, tag, frame)) do\n      Ok(_) -> \"\"\n      Err(e) ->\n        send(p.ep, PeerGone(p, l.role, \"connection lost\"))\n        e\n    end\n  end\n\n  -- The heartbeat, one per connection, from the moment it is made\n  -- (`start_link`): every interval, ping the peer on the data connection\n  -- (through its NodeQueue writer, which serialises every write to that\n  -- socket) and, once this side reads the connection (`serve`), count one\n  -- tick since the peer's last frame. Past the limit the peer is taken for\n  -- dead (`drop_link`, \"no heartbeat\"). A peer that is stopped, hung or\n  -- behind a partition sends no end of file, so without this the reader\n  -- would wait forever. Ticks are not counted before the reader runs: the\n  -- peer's frames, pings included, are not read yet, so nothing could\n  -- reset the count, and a role driving to its first suspension would take\n  -- its peers for dead. Stops once the reader has, or setup was abandoned.\n  -- A ping is the one frame that may be dropped (`DropNew`): when the queue\n  -- is full, data frames are already telling the peer we are alive.\n  -- MARCH_SESSION_HEARTBEAT_MS (default 1000) and MARCH_SESSION_TIMEOUT_MS\n  -- (default 10000) tune it.\n  -- (interval, limit in ticks): MARCH_SESSION_HEARTBEAT_MS (default 1000;\n  -- <= 0 turns the heartbeat off) and MARCH_SESSION_TIMEOUT_MS (default\n  -- 10000).\n  pfn heartbeat_config() : (Int, Int) do\n    let interval = Env.get_int(\"MARCH_SESSION_HEARTBEAT_MS\", 1000)\n    let timeout = Env.get_int(\"MARCH_SESSION_TIMEOUT_MS\", 10000)\n    (interval, if interval > 0 do timeout / interval else 0 end)\n  end\n\n  pfn heartbeat(p : Party, l : Link, interval : Int, limit : Int) : Int do\n    sleep_ms(interval)\n    if Vault.get(p.meta, \"link_done\" ++ rkey(l.role)) != None || Vault.get(p.meta, \"open\") == None do 0\n    else\n      -- A drained party is done but still serving: its peers read its\n      -- connection until its Bye, which waits for their own end (D27).\n      if Vault.get(p.meta, \"done\") == None || drained_here(p) do\n        let _ = NodeQueue.cast(l.q, next_seq(p.meta), l.peer, \"SessionNode.Ping\", Nil, NodeQueue.DropNew)\n        ()\n      else () end\n      let ticks = if Vault.get(p.meta, \"reading\" ++ rkey(l.role)) == None do 0\n                  else Vault.incr(p.heard, rkey(l.role), 1) end\n      if ticks > limit do\n        drop_link(p, l, \"no heartbeat\")\n        0\n      else\n        heartbeat(p, l, interval, limit)\n      end\n    end\n  end\n\n  -- The readers' outcome, from the endpoint actor. Asked again every\n  -- second (the actor keeps only the newest asker, see `AwaitOutcome`), so a\n  -- dead endpoint actor is noticed: `Actor.call` does not return early when\n  -- its target dies.\n  pfn await_outcome(p : Party) : List((Int, String)) do\n    match Actor.call(p.ep, OutcomeReq, 1000) do\n      Ok(failed) -> failed\n      Err(_) ->\n        if is_alive(p.ep) do await_outcome(p)\n        else\n          endpoint_died(p)\n          Nil\n        end\n    end\n  end\n\n  -- The party's endpoint actor is dead. It holds the session's epoch\n  -- (`party`), so a hot-reload hard drain deadline kills it with\n  -- Crash(\"draining\") (plan 6.2, follow-up 3): the session ends as\n  -- `Left(\"draining\")`, as a hosted one whose host was killed does. Any\n  -- other death is a cancellation naming it. Runs in the runner's own task,\n  -- after the actor's turns are over, so the Vaults are no longer shared.\n  -- The peers are told by the connection ending (standalone: both sockets\n  -- are shut down, which their readers see at once); a cluster party's\n  -- connections are the node's and stay up, and the peers learn from their\n  -- own endpoint's failure detection.\n  pfn endpoint_died(p : Party) : () do\n    let why = match actor_terminal_reason(pid_to_int(p.ep)) do\n      Some((_tag, m)) -> m\n      None -> \"\"\n    end\n    if ep_done(p) do () else\n      Vault.set(p.meta, \"done\", 1)\n      if why == \"draining\" do\n        Vault.set(p.meta, \"kind\", kind_left())\n        Vault.set(p.meta, \"cancel_role\", p.my_role)\n        Vault.set(p.why, \"cancel_cause\", \"draining\")\n      else\n        Vault.set(p.meta, \"kind\", kind_cancelled())\n        Vault.set(p.meta, \"cancel_role\", p.my_role)\n        Vault.set(p.why, \"cancel_cause\", \"session endpoint gone\" ++ (if why == \"\" do \"\" else \": \" ++ why end))\n      end\n    end\n    if is_cluster(p) do () else\n      let _ = List.map(p.links, fn l -> do\n        Vault.set(p.meta, \"link_done\" ++ rkey(l.role), 1)\n        tcp_shutdown(l.data_fd)\n        tcp_shutdown(l.control_fd)\n        0\n      end)\n      -- The shutdown wakes each data reader with an end of file; wait for\n      -- it to have RUN before `finish` closes the socket, or the close drops\n      -- its parked wait and the task never ends (the process would not\n      -- exit). Bounded: a reader that never started (`serve_outcome` not\n      -- reached) has no flag to set.\n      let _ = List.map(p.links, fn l -> await_reader(p, l.role, 500))\n      ()\n    end\n  end\n\n  pfn await_reader(p : Party, role : Int, tries : Int) : () do\n    if tries <= 0 || Vault.get(p.meta, \"reading\" ++ rkey(role)) == None\n       || Vault.get(p.meta, \"reader_done\" ++ rkey(role)) != None do ()\n    else\n      sleep_ms(10)\n      await_reader(p, role, tries - 1)\n    end\n  end\n\n  doc \"\"\"\n  Read deliveries from every peer until each connection has ended: the\n  peer closed, was cancelled, or went away. A peer's failure no longer ends\n  the session for this node at once: it cancels our endpoint only if our\n  endpoint is waiting on that peer with nothing from it queued (Maty's\n  rule; see the module comment), and cancellation then spreads to our other\n  peers as a Cancel frame. `Nil` if our endpoint ended normally, else\n  `(role, cause)` for its cancellation. Every resumption runs in this\n  node's endpoint actor, so call it after driving the local role to its\n  first suspension. `serve` panics on a cancellation; `run` returns it.\n  \"\"\"\n  fn serve_outcome(p : Party) : List((Int, String)) do\n    send(p.ep, Expect(List.length(p.links)))\n    -- The heartbeats are already running (`start_link`); from here they\n    -- also count the silence on each connection.\n    let _ = List.map(p.links, fn l -> Vault.set(p.meta, \"reading\" ++ rkey(l.role), 1))\n    let _ = List.map(p.links, fn l -> task_spawn(fn _ -> do\n      let why = read_link(p, l)\n      Vault.set(p.meta, \"link_done\" ++ rkey(l.role), 1)\n      -- For `endpoint_died`, which must not let `finish` close this socket\n      -- under a reader still parked in it (a close drops the parked wait;\n      -- only the shutdown wakes it, and the reader has to run first).\n      Vault.set(p.meta, \"reader_done\" ++ rkey(l.role), 1)\n      send(p.ep, LinkEnded(l.role, why))\n      0\n    end))\n    let _ = await_outcome(p)\n    -- Every connection has ended. An endpoint still waiting now waits on\n    -- nobody: that is a cancellation too (a hosted one gets its host's turn\n    -- first, `await_hosted_end`).\n    await_hosted_end(p, connect_ms())\n    if ep_done(p) do () else\n      match Vault.get(p.meta, \"ep\") do\n        Some(ep) -> cancel_endpoint(p, ep, 0, \"every peer is gone\", \"every peer is gone\", kind_cancelled())\n        None -> Vault.set(p.meta, \"done\", 1)\n      end\n    end\n    match Vault.get(p.meta, \"kind\") do\n      None -> Nil\n      Some(_) -> Cons((Vault.get_or(p.meta, \"cancel_role\", 0), Vault.get_or(p.why, \"cancel_cause\", \"\")), Nil)\n    end\n  end\n\n  doc \"`serve_outcome`, panicking if our endpoint was cancelled; the transport's original contract.\"\n  fn serve(p : Party) : Unit do\n    match serve_outcome(p) do\n      Nil -> ()\n      Cons((role, why), _) -> panic(\"session_node: cancelled (role \" ++ int_to_string(role) ++ \"): \" ++ why)\n    end\n  end\n\n  doc \"\"\"\n  Drain every code epoch this process runs, as the reload server's\n  `DRAIN epoch:<current>` does: every session on this node ends at its next\n  loop boundary (D27; `run_<Role>` returns `Ok(Session.Drained(n))`), actors\n  still on an old epoch get a marker at [soft_ms], and at [hard_ms] (> 0)\n  whatever is still pinned is stopped. `Topology.drain` calls it on SIGTERM.\n  Takes `Cap(IO)`: it ends sessions it does not own.\n  \"\"\"\n  fn drain_epochs(_io : Cap(IO), soft_ms : Int, hard_ms : Int) : () do\n    epoch_drain(soft_ms, hard_ms)\n  end\n\n  -- The party's session is over: release the Endpoint's epoch hold and end\n  -- the actor, whose reap drops its pin (review finding 2026-09-24-dd-review-\n  -- cluster-party-never-releases-epoch-hold: a party that outlived its\n  -- session pinned its epoch for the life of the process). Every exit of\n  -- every runner passes here: `finish`, the cluster runner's success and\n  -- error arms, and the standalone runner's join failure.\n  pfn end_party(p : Party) : () do\n    let _ = send(p.ep, ReleaseEpoch())\n    kill(p.ep)\n  end\n\n  doc \"Tear every connection down: close data, Bye on control, await the control reader, close control, and end the party's Endpoint actor (a cluster-mode party owns no connection: only the actor ends). Then retire the party's tables: call it once `serve` / `serve_outcome` has returned.\"\n  fn finish(p : Party) : Unit do\n    finish_links(p)\n    close_party(p)\n  end\n\n  -- `finish` without retiring the tables, for the runner, which reads the\n  -- outcome out of them afterwards and retires them itself.\n  pfn finish_links(p : Party) : () do\n    end_party(p)\n    let _ = if is_cluster(p) do Nil else List.map(p.links, fn l -> do\n      -- Its reader has ended, which stopped its heartbeat; a party that\n      -- never served stops it here.\n      Vault.set(p.meta, \"link_done\" ++ rkey(l.role), 1)\n      tcp_close(l.data_fd)\n      let _ = NodeSend.cast(l.control_fd, 0, GlobalPid.make(\"peer\", 0, 0), \"SessionNode.Bye\", Nil)\n      let _ = task_await(l.control)\n      tcp_close(l.control_fd)\n      0\n    end) end\n    ()\n  end\n\n  -- \u2500\u2500 the role runner \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- Everything above, from a role, its peer set and an address table, in\n  -- the one order that cannot deadlock: connect to every LOWER role\n  -- (ascending), then accept every HIGHER one. Role 1 has nothing to connect\n  -- to, so it is accepting at once; role k connects only to roles below it,\n  -- each of which finished its own connects and is accepting. No node ever\n  -- waits on a node that is waiting on it. No wait is unbounded either: a\n  -- dial retries, an accept waits, and each handshake and hello reads, for\n  -- at most MARCH_SESSION_CONNECT_MS (`connect_ms`), and a setup that fails\n  -- tears down what it built (`abort_links`), so a role that never starts,\n  -- or fails its own setup, fails the others' setup too instead of holding\n  -- them for ever (specs/progress/2026-09-18-session-accept-deadline.md).\n  --\n  -- Addresses are a runtime value; their SHAPE is checked here from what the\n  -- compiler knows (`peers_<R>()`): a role needs its own entry iff some peer\n  -- is above it, and an entry for every peer below it. A missing one fails\n  -- at startup, by role, before any socket opens.\n\n  -- Where a role listens: its own entry says where; a peer's entry says\n  -- where to dial it.\n  type Addr = { role : Int, host : String, port : Int }\n  -- Signatures below say `List(Addr)` outright: an alias does not unify\n  -- with its expansion across a module boundary, and a caller building the\n  -- table by hand (`Cons(addr, Nil)`) must be able to pass it.\n  type Addrs = List(Addr)\n\n  -- Why `run` ended other than by the protocol reaching its end. A session\n  -- is not resumable: a peer that is gone ends it for everyone, and `run`\n  -- returns rather than hanging on it. What to do next (run again: a fresh\n  -- party and fresh connections) is the caller's decision.\n  --\n  -- - `Cancelled(role, cause)`: this role's endpoint was cancelled because\n  --   it was waiting on `role`, which can send nothing more, and nothing\n  --   from it was queued. `cause` is the chain back to where the failure\n  --   began (\"role 3: connection lost\"). A peer that fails AFTER this role\n  --   no longer needs it does not cancel it: `run` returns `Ok`.\n  -- - `Protocol(role, why)`: that peer sent what cannot be delivered -- a\n  --   message the generated code could not decode or one its state cannot\n  --   receive (`Session.fail`). Our endpoint is cancelled and the peers are\n  --   told.\n  -- - `HostGone(ep)`: a hosted party's actor is gone (crashed or\n  --   restarted); its parked session state died with it. The peers are sent\n  --   a Cancel.\n  -- - `Left(why)`: this role called `leave`.\n  -- - `Listen(port, why)` / `Accept(why)` / `Connect(role, why)`: wiring.\n  -- - `NoOffer(role, why)`: `initiate` found no access point that would\n  --   take [role] (none registered, all full, all refused, or no answer).\n  -- - `AlreadyOffered(role)`: this node already offers [role] of that protocol.\n  -- - `Unauthorized(role, why)`: certificate mode (step 11b), and this node's\n  --   own certificate does not let it offer [role].\n  type RunError = Cancelled(Int, String) | Protocol(Int, String) | HostGone(Int) | Left(String) | Listen(Int, String) | Accept(String) | Connect(Int, String) | NoOffer(Int, String) | AlreadyOffered(Int) | Unauthorized(Int, String)\n\n  doc \"\"\"\n  A one-line, human-readable description of [e], prefixed\n  `\"session_node: \"`, with roles shown as their numbers (see\n  `run_error_message_named` for role names). For example\n  `Connect(2, \"refused\")` gives `\"session_node: connect to role 2: refused\"`.\n  \"\"\"\n  fn run_error_message(e : RunError) : String do\n    run_error_message_named(e, fn i -> int_to_string(i))\n  end\n\n  doc \"\"\"\n  `run_error_message` with roles shown by [name] (the generated\n  `<P>_Msg.role_name`): what `<P>_Run.error_message` is.\n  \"\"\"\n  fn run_error_message_named(e : RunError, name : Int -> String) : String do\n    match e do\n      Cancelled(role, why) -> \"session_node: cancelled while waiting on role \" ++ name(role) ++ \": \" ++ why\n      RunError.Left(why) -> \"session_node: left the session: \" ++ why\n      Protocol(role, why) -> \"session_node: role \" ++ name(role) ++ \": \" ++ why\n      HostGone(ep) -> \"session_node: endpoint \" ++ int_to_string(ep) ++ \": its host actor is gone and the parked session state with it; session abandoned\"\n      Listen(port, why) -> \"session_node: listen on port \" ++ int_to_string(port) ++ \": \" ++ why\n      RunError.Accept(why) -> \"session_node: accept: \" ++ why\n      RunError.Connect(role, why) -> \"session_node: connect to role \" ++ name(role) ++ \": \" ++ why\n      NoOffer(role, why) -> \"session_node: no access point for role \" ++ name(role) ++ \": \" ++ why\n      AlreadyOffered(role) -> \"session_node: role \" ++ name(role) ++ \" is already offered on this node\"\n      Unauthorized(role, why) -> \"session_node: role \" ++ name(role) ++ \": \" ++ why\n    end\n  end\n\n  doc \"The peers [my_role] dials: those below it, ascending (i < j: i listens, j connects).\"\n  fn dials(my_role : Int, peers : List(Int)) : List(Int) do\n    List.sort_by(List.filter(peers, fn r -> r < my_role), fn (a, b) -> a < b)\n  end\n\n  doc \"The peers [my_role] accepts: those above it.\"\n  fn accepts(my_role : Int, peers : List(Int)) : List(Int) do\n    List.filter(peers, fn r -> r > my_role)\n  end\n\n  doc \"The first entry in [addrs] for [role], or `None` if it has none.\"\n  fn addr_of(addrs : List(Addr), role : Int) : Option(Addr) do\n    List.find(addrs, fn a -> a.role == role)\n  end\n\n  pfn has_addr(addrs : List(Addr), role : Int) : Bool do\n    match addr_of(addrs, role) do\n      Some(_) -> true\n      None -> false\n    end\n  end\n\n  doc \"\"\"\n  The roles [my_role] needs an address for and [addrs] lacks: every peer it\n  dials, and itself if it accepts anyone. Empty means `run` can start.\n  \"\"\"\n  fn missing_addrs(my_role : Int, peers : List(Int), addrs : List(Addr)) : List(Int) do\n    let need = match accepts(my_role, peers) do\n      Nil -> dials(my_role, peers)\n      _ -> Cons(my_role, dials(my_role, peers))\n    end\n    List.filter(need, fn r -> has_addr(addrs, r) == false)\n  end\n\n  doc \"Parse `host:port` into the entry for [role].\"\n  fn parse_addr(role : Int, s : String) : Result(Addr, String) do\n    match String.split_first(s, \":\") do\n      None -> Err(\"session_node: address \" ++ s ++ \" is not host:port\")\n      Some((host, port_s)) ->\n        match String.to_int(port_s) do\n          Ok(port) -> Ok({ role: role, host: host, port: port })\n          Err(_) -> Err(\"session_node: address \" ++ s ++ \" has a bad port\")\n        end\n    end\n  end\n\n  doc \"\"\"\n  One entry per role from the environment: `<PREFIX>_<ROLE>_ADDR = host:port`\n  (upper-cased) for each `(name, index)` in [roles], the generated\n  `<P>_Msg.role_names()`. An unset variable is no entry, and `run` names the\n  roles it needed; a set one that does not parse panics. The generated\n  `<P>_Run.addrs_from_env()` passes the protocol's name and roles.\n  \"\"\"\n  fn addrs_from_env(prefix : String, roles : List((String, Int))) : List(Addr) do\n    List.flat_map(roles, fn r -> match r do\n      (name, idx) ->\n        let key = String.to_uppercase(prefix ++ \"_\" ++ name ++ \"_ADDR\")\n        match process_env(key) do\n          None -> Nil\n          Some(v) ->\n            match parse_addr(idx, v) do\n              Ok(a) -> Cons(a, Nil)\n              Err(e) -> panic(e ++ \" (\" ++ key ++ \")\")\n            end\n        end\n    end)\n  end\n\n  -- How long setup waits on a peer: to dial a role that is still starting,\n  -- for a role to connect, and for each handshake and hello once it has.\n  -- MARCH_SESSION_CONNECT_MS (default 20000); <= 0 waits for ever.\n  pfn connect_ms() : Int do\n    Env.get_int(\"MARCH_SESSION_CONNECT_MS\", 20000)\n  end\n\n  -- Dial [a] every 100 ms until it answers or [attempts] run out (connect_ms\n  -- worth), each handshake bounded by [timeout_ms].\n  -- [auth] is the node's (`ClusterNode.auth_from_env`): a shared secret, or\n  -- its certificate (step 11b), in which case the peer's verified\n  -- certificate comes back with the connection.\n  pfn dial_retry(a : Addr, me, auth : ClusterAuth.Auth, attempts : Int, timeout_ms : Int)\n      : Result((Peer, Option(NodeCert.Cert)), String) do\n    match ClusterConn.connect_split_auth(PeerRegistry.empty(), a.host, a.port, me, auth, timeout_ms) do\n      Ok((_reg, conn, cert)) -> Ok((conn, cert))\n      Err(e) ->\n        -- The peer answered and rejected the handshake: retrying cannot\n        -- help, and the peer has given up on this node, so a retry would\n        -- only be refused and hide the real reason.\n        if String.starts_with(e, \"Handshake:\") do\n          match auth do\n            ClusterAuth.Secret(_) -> Err(e ++ \" (do both nodes run with the same secret?)\")\n            ClusterAuth.Certified(_) -> Err(e)\n          end\n        else if attempts <= 1 do\n          Err(e)\n        else\n          sleep_ms(100)\n          dial_retry(a, me, auth, attempts - 1, timeout_ms)\n        end end\n    end\n  end\n\n  -- The direct runner's two-way role check (step 11b): in certificate mode\n  -- the peer's verified certificate must let it play role [r] of [proto]\n  -- (either mode: a direct session has no offer or initiator). Always Ok\n  -- with a shared secret.\n  pfn direct_role_ok(auth : ClusterAuth.Auth, cert : Option(NodeCert.Cert), proto : String,\n                     roles : List((String, Int)), r : Int, who : String) : Result((), String) do\n    match auth do\n      ClusterAuth.Secret(_) -> Ok(())\n      ClusterAuth.Certified(_) ->\n        let name = SessionAP.role_name(roles, r)\n        match SessionAP.authorize(cert, proto, name, SessionAP.offer_mode()) do\n          Ok(_) -> Ok(())\n          Err(_) ->\n            match SessionAP.authorize(cert, proto, name, SessionAP.initiate_mode()) do\n              Ok(_) -> Ok(())\n              Err(why) -> Err(\"role \" ++ SessionAP.role_label(proto, name) ++ \" is played by \" ++ who ++ \": \" ++ why)\n            end\n        end\n    end\n  end\n\n  -- Every setup failure below tears down the connections made so far\n  -- (`abort_links`), so the peers already reached learn of it at once.\n  pfn dial_all(p : Party, roles : List(Int), addrs : List(Addr), me, auth : ClusterAuth.Auth, fingerprint : String,\n               proto : String, names : List((String, Int))) : Result(Party, RunError) do\n    match roles do\n      Nil -> Ok(p)\n      Cons(r, rest) ->\n        match addr_of(addrs, r) do\n          None ->\n            abort_links(p)\n            Err(RunError.Connect(r, \"no address\"))\n          Some(a) ->\n            let t = connect_ms()\n            let attempts = if t > 0 do if t / 100 > 1 do t / 100 else 1 end else 1000000000 end\n            match dial_retry(a, me, auth, attempts, t) do\n              Err(e) ->\n                abort_links(p)\n                Err(RunError.Connect(r, e))\n              Ok((conn, cert)) ->\n                match direct_role_ok(auth, cert, proto, names, r, conn.identity.name) do\n                  Err(e) ->\n                    close_peer(conn)\n                    abort_links(p)\n                    Err(RunError.Connect(r, e))\n                  Ok(_) ->\n                    match join_dialed(p, r, conn, t, fingerprint) do\n                      Err(e) ->\n                        abort_links(p)\n                        Err(RunError.Connect(r, e))\n                      Ok(p2) -> dial_all(p2, rest, addrs, me, auth, fingerprint, proto, names)\n                    end\n                end\n            end\n        end\n    end\n  end\n\n  pfn last_role(links : List(Link)) : Int do\n    match links do\n      Nil -> 0\n      Cons(l, Nil) -> l.role\n      Cons(_, rest) -> last_role(rest)\n    end\n  end\n\n  -- Accept one connection per role in [expected], in whatever order they\n  -- arrive: the hello says which role it is. A role not expected, or seen\n  -- twice, is a wiring mistake and fails loudly. Gives up when no expected\n  -- role connects within connect_ms (each accept waits that long, so a\n  -- cluster whose roles keep arriving is never cut off): a role that never\n  -- starts, or failed its own setup, no longer holds this one for ever.\n  pfn accept_all(p : Party, expected : List(Int), listen_fd : Int, me, auth : ClusterAuth.Auth, fingerprint : String,\n                 proto : String, names : List((String, Int))) : Result(Party, RunError) do\n    match expected do\n      Nil -> Ok(p)\n      _ ->\n        let t = connect_ms()\n        match ClusterConn.accept_split_auth(PeerRegistry.empty(), listen_fd, me, auth, t) do\n          Err(e) ->\n            abort_links(p)\n            if e == \"tcp_accept: timed out\" do\n              Err(RunError.Accept(\"no connection from role(s) \" ++ show_roles(expected) ++ \" within \" ++ int_to_string(t) ++ \" ms\"))\n            else Err(RunError.Accept(e)) end\n          Ok((_reg, conn, cert)) ->\n            match join_accepted(p, conn, t, fingerprint) do\n              Err(e) ->\n                abort_links(p)\n                Err(RunError.Accept(e))\n              Ok(p2) ->\n                let got = last_role(p2.links)\n                if List.member(expected, got) == false do\n                  panic(\"session_node: role \" ++ int_to_string(p.my_role) ++ \" accepted a connection from role \"\n                        ++ int_to_string(got) ++ \" but expects role(s) \" ++ show_roles(expected))\n                else () end\n                -- The role comes from the peer's hello: its certificate must\n                -- allow it (step 11b).\n                match direct_role_ok(auth, cert, proto, names, got, conn.identity.name) do\n                  Err(e) ->\n                    abort_links(p2)\n                    Err(RunError.Accept(e))\n                  Ok(_) -> accept_all(p2, List.filter(expected, fn r -> r != got), listen_fd, me, auth, fingerprint, proto, names)\n                end\n            end\n        end\n    end\n  end\n\n  pfn open_listener(my_role : Int, higher : List(Int), addrs : List(Addr)) : Result(Int, RunError) do\n    match higher do\n      Nil -> Ok(-1)\n      _ ->\n        match addr_of(addrs, my_role) do\n          None -> Ok(-1)   -- unreachable: missing_addrs was checked first\n          Some(a) ->\n            match tcp_listen(a.port) do\n              Ok(fd) -> Ok(fd)\n              Err(e) -> Err(Listen(a.port, e))\n            end\n        end\n    end\n  end\n\n  doc \"\"\"\n  Run role [my_role] of a session on this node: listen if any peer is above\n  it, connect to every peer below it (ascending, with retry), accept every\n  peer above it, check the party against [peers] (`<P>_Msg.peers_<R>()`),\n  attach, run [body] to its first suspension, serve, and tear down. [addrs]\n  must hold this role's own entry iff it accepts anyone and an entry for\n  every peer it dials; a missing one panics by role before any socket opens.\n  [node_id] names this node in the handshake and [secret] is the cluster\n  secret every node shares; with MARCH_NODE_CERT set the node runs in\n  certificate mode instead (`ClusterNode.auth_from_env`, the variables a\n  cluster node reads), and each peer's certificate must let it play the\n  role it announces in [proto] (named by [roles], `<P>_Msg.role_names()`),\n  else setup fails with `Connect`/`Accept` \"role P.R is played by <node>:\n  not authorized for P.R\". [fingerprint] is the protocol's own\n  (`<P>_Msg.fingerprint()`): it rides the hello, and a peer whose own differs\n  -- or that is too old to send one at all -- is refused at setup with a\n  `Connect`/`Accept` error rather than discovered mid-session as an\n  undecodable message (2026-09-21). `\"\"` asks for no check. The generated\n  `<P>_Run.run_<Role>` supplies the role, its peers, the fingerprint and the\n  typed entry state.\n\n  `Ok(Session.Finished)` when every peer's endpoint closed, `Ok(Session.Drained(n))`\n  when the session was ended at a loop boundary by a drain (D27; [n] of this\n  role's messages came back undelivered); else the `RunError` that ended\n  the session, after the party has been torn down.\n  \"\"\"\n  fn run(io : Cap(IO), my_role : Int, peers : List(Int), node_id : String, secret : String,\n         addrs : List(Addr), fingerprint : String, proto : String, roles : List((String, Int)),\n         on_close : Int -> Unit, body : Cap(Session.Live) -> Unit) : Result(Session.Outcome, RunError) do\n    run_party(io, my_role, peers, node_id, secret, addrs, fingerprint, proto, roles, on_close, fn (_p, s) -> body(s))\n  end\n\n  doc \"\"\"\n  `run`, with the role HOSTED IN AN ACTOR [host] (its pid as an Int,\n  `pid_to_int`): the generated event API (`Parked_<Role>` in the actor's\n  state, `await_*`/`resume`) instead of a body. [start] runs once the party\n  is connected, with the session capability: send it to the actor, whose\n  start handler registers and parks. [deliver] is called for every delivery\n  the actor's parked endpoint awaits -- `(s, from, msg, ep)`, what its resume\n  handler takes: send them on. Deliveries are one per suspension, in mailbox\n  order, and one that arrives before the host has re-parked is held for it.\n\n  The host is monitored: its `Down` (a crash, a kill, a supervisor's restart)\n  cancels its role with `Err(HostGone(ep))`, and the peers are sent a Cancel\n  (they are cancelled in turn only if they were waiting on it). A restarted\n  actor starts `Idle` and cannot continue a session its predecessor parked;\n  run again for a new one. `run_hosted_or` also tells the actor itself. The\n  generated `<P>_Run.host_<Role>` supplies the role and its peers.\n  \"\"\"\n  fn run_hosted(io : Cap(IO), my_role : Int, peers : List(Int), node_id : String, secret : String,\n                addrs : List(Addr), fingerprint : String, proto : String, roles : List((String, Int)),\n                on_close : Int -> Unit, host : Int,\n                start : Cap(Session.Live) -> Unit,\n                deliver : Cap(Session.Live) -> Int -> Bytes -> Int -> Unit) : Result(Session.Outcome, RunError) do\n    run_hosted_or(io, my_role, peers, node_id, secret, addrs, fingerprint, proto, roles, on_close, host, start, deliver,\n                  fn (_s, _role, _cause, _ep) -> ())\n  end\n\n  doc \"\"\"\n  `run_hosted`, telling the actor when its endpoint is cancelled: [cancel]\n  gets `(s, role, cause, ep)` -- the role it was waiting on and why that\n  role is gone. Send it to the actor, whose handler stores the generated\n  `<P>_<Role>.cancel(state.parked)` (a `Closed` parked value) and may update\n  the rest of its state; it cannot communicate in the cancelled session.\n  \"\"\"\n  fn run_hosted_or(io : Cap(IO), my_role : Int, peers : List(Int), node_id : String, secret : String,\n                   addrs : List(Addr), fingerprint : String, proto : String, roles : List((String, Int)),\n                   on_close : Int -> Unit, host : Int,\n                   start : Cap(Session.Live) -> Unit,\n                   deliver : Cap(Session.Live) -> Int -> Bytes -> Int -> Unit,\n                   cancel : Cap(Session.Live) -> Int -> String -> Int -> Unit) : Result(Session.Outcome, RunError) do\n    run_party(io, my_role, peers, node_id, secret, addrs, fingerprint, proto, roles, on_close,\n              fn (p, s) -> host_party(p, s, host, start, deliver, cancel))\n  end\n\n  -- The hosted party's setup, once the party is formed and attached as [s]:\n  -- deliveries and cancellations for the awaiting endpoint go to the actor\n  -- through the two forwards, a `HostWatch` monitors the host [host] (its\n  -- pid as an Int) for the session's whole life, and the actor is started.\n  -- Shared by the standalone runner (`run_hosted_or`) and the cluster one\n  -- (`run_cluster_hosted_with`); the session's end must `stop_host_watch`.\n  pfn host_party(p : Party, s : Cap(Session.Live), host : Int, start : Cap(Session.Live) -> Unit,\n                 deliver : Cap(Session.Live) -> Int -> Bytes -> Int -> Unit,\n                 cancel : Cap(Session.Live) -> Int -> String -> Int -> Unit) : () do\n    Vault.set(p.forward, \"f\", fn (from, msg, ep) -> deliver(s, from, msg, ep))\n    Vault.set(p.forward_cancel, \"c\", fn (role, cause, ep) -> cancel(s, role, cause, ep))\n    -- A crash the actor has a branch for goes the DELIVERY way, to the same\n    -- callback, so the actor's resume handler takes it with `state` in scope\n    -- exactly as it takes a message (`Session.crash_payload`).\n    Vault.set(p.forward_crash, \"x\", fn (role, cause, ep) -> deliver(s, role, Session.crash_payload(cause), ep))\n    let w = spawn(HostWatch)\n    send(w, Watch(p, p.my_role))\n    let _ = monitor(w, pid_of_int(host))\n    Vault.set(p.meta, \"watch\", pid_to_int(w))\n    start(s)\n  end\n\n  -- Kill the party's `HostWatch`, if it has one, so it is not left parked in\n  -- `receive` after the session ended. A no-op for a callback-mode party.\n  pfn stop_host_watch(p : Party) : () do\n    match Vault.get(p.meta, \"watch\") do\n      Some(w) -> kill(pid_of_int(w))\n      None -> ()\n    end\n  end\n\n  pfn run_party(io : Cap(IO), my_role : Int, peers : List(Int), node_id : String, secret : String,\n                addrs : List(Addr), fingerprint : String, proto : String, roles : List((String, Int)),\n                on_close : Int -> Unit,\n                drive : Party -> Cap(Session.Live) -> Unit) : Result(Session.Outcome, RunError) do\n    match missing_addrs(my_role, peers, addrs) do\n      Nil -> ()\n      missing -> panic(\"session_node: role \" ++ int_to_string(my_role) ++ \" needs an address for role(s) \" ++ show_roles(missing))\n    end\n    let me = NodeIdentity.make(node_id, \"pk-\" ++ node_id, 1)\n    -- Certificate mode when MARCH_NODE_CERT is set, as for a cluster node\n    -- (step 11b); else the shared [secret].\n    let? auth = match ClusterNode.auth_from_env(node_id, secret) do\n      Ok(a) -> Ok(a)\n      Err(e) -> Err(RunError.Connect(my_role, e))\n    end\n    let higher = accepts(my_role, peers)\n    let? listen_fd = open_listener(my_role, higher, addrs)\n    let p0 = party(my_role, node_id, on_close)\n    let joined = match dial_all(p0, dials(my_role, peers), addrs, me, auth, fingerprint, proto, roles) do\n      Err(e) -> Err(e)\n      Ok(p1) -> accept_all(p1, higher, listen_fd, me, auth, fingerprint, proto, roles)\n    end\n    match joined do\n      Err(e) ->\n        if listen_fd >= 0 do tcp_close(listen_fd) else () end\n        end_party(p0)\n        close_party(p0)\n        Err(e)\n      Ok(p2) -> serve_party(p2, io, my_role, peers, listen_fd, drive)\n    end\n  end\n\n  pfn serve_party(p2 : Party, io : Cap(IO), my_role : Int, peers : List(Int), listen_fd : Int,\n                  drive : Party -> Cap(Session.Live) -> Unit) : Result(Session.Outcome, RunError) do\n    let p = require(p2, peers)\n    let o = ops(p)\n    let s = Session.attach(io, o)\n    drive(p, s)\n    let _ = serve_outcome(p)\n    finish_links(p)\n    if listen_fd >= 0 do tcp_close(listen_fd) else () end\n    stop_host_watch(p)\n    let r = run_result(p, my_role)\n    close_party(p)\n    retire_ops(o)\n    r\n  end\n\n  -- The session capability IS the Ops record (Session.attach stores it as the\n  -- capability's dictionary), but a reference released as a Cap(Session.Live)\n  -- is released as one cell: when the capability's last holder let go, the\n  -- record was freed and its ten closures, every one capturing the Party,\n  -- leaked -- the Party and its thirteen table handles, per party, per session\n  -- (specs/progress/2026-10-06-session-ops-leak.md). The runner keeps a\n  -- reference of the record's own type to the end and releases it last, so the\n  -- final release is the deep one.\n  pfn retire_ops(o : Session.Ops) : () do\n    let _ = o\n    ()\n  end\n\n  -- \u2500\u2500 the cluster runner \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- `run`, over a running cluster node instead of per-session connections\n  -- (specs/progress/2026-09-18-cluster-node-service.md, phase 4). Each role\n  -- registers its endpoint under \"session:<sid>/<role>\" and finds its peers'\n  -- by name; frames ride the node's data queues and reach the endpoint\n  -- through a route on its pid; a peer whose node's data connection ends --\n  -- SWIM declared the node dead, or the connection was lost -- is gone, told\n  -- from that connection's reader after its last delivery (the drain rule's\n  -- ordering). No heartbeat: SWIM is the failure detector. Every role must\n  -- be on a different node (a node has no connection to itself).\n\n  pfn role_name(session : String, role : Int) : String do\n    \"session:\" ++ session ++ \"/\" ++ int_to_string(role)\n  end\n\n  -- The protocol fingerprint rides the registry as a second name beside the\n  -- role's, \"session:<sid>/<role>#<fingerprint>\", bound to the same endpoint:\n  -- a registry binding carries a pid and nothing else, and `cluster_<Role>`\n  -- has no hello of its own to put it in (todo 2026-09-21, the cluster half\n  -- of 2026-09-21-protocol-fingerprint-payload-definitions). Registered\n  -- BEFORE the role's own name, so a peer that found the role finds this\n  -- too, or does shortly after (`check_peer_fingerprints` waits a little).\n  pfn fingerprint_name(session : String, role : Int, fingerprint : String) : String do\n    role_name(session, role) ++ \"#\" ++ fingerprint\n  end\n\n  -- The fingerprint role [role] of [session] registered, if any.\n  pfn peer_fingerprint(node : Cap(ClusterNode.Live), session : String, role : Int) : Option(String) do\n    let prefix = role_name(session, role) ++ \"#\"\n    let n = String.byte_size(prefix)\n    match List.find(ClusterNode.names(node), fn nm -> String.starts_with(nm, prefix)) do\n      Some(nm) -> Some(String.slice_bytes(nm, n, String.byte_size(nm) - n))\n      None -> None\n    end\n  end\n\n  doc \"\"\"\n  Whether every peer in [found] registered the fingerprint [mine]: the\n  `cluster_<Role>` counterpart of `hello_verdict`. `\"\"` checks nothing (an\n  access point's session: its Invite already carried the fingerprint, and\n  its compatibility table may admit a different one). A peer that registered\n  none within [left] ms was built before the check and is refused, as a\n  hello with no fingerprint is. `Err((role, why))` names the first peer\n  refused.\n  \"\"\"\n  pfn check_peer_fingerprints(node : Cap(ClusterNode.Live), session : String, found : List((Int, GlobalPid.Pid)),\n                              mine : String, left : Int) : Result((), (Int, String)) do\n    if mine == \"\" do Ok(())\n    else\n      let bad = List.find(found, fn rg ->\n        match rg do (r, _g) -> peer_fingerprint(node, session, r) != Some(mine) end)\n      match bad do\n        None -> Ok(())\n        Some((r, _g)) ->\n          match peer_fingerprint(node, session, r) do\n            Some(theirs) ->\n              Err((r, \"role \" ++ int_to_string(r) ++ \"'s node was built from a DIFFERENT version of the \"\n                      ++ \"protocol (fingerprint \" ++ mine ++ \" here, \" ++ theirs ++ \" there). Rebuild both \"\n                      ++ \"from the same source.\"))\n            None ->\n              if left <= 0 do\n                Err((r, \"role \" ++ int_to_string(r) ++ \"'s endpoint registered no protocol fingerprint, so \"\n                        ++ \"its node was built before cluster sessions carried one; the two sides cannot be \"\n                        ++ \"shown to run the same protocol. Rebuild both from the same source.\"))\n              else\n                sleep_ms(50)\n                check_peer_fingerprints(node, session, found, mine, left - 50)\n              end\n          end\n      end\n    end\n  end\n\n  -- Unregister role [me]'s names: the role's own, its fingerprint's, and\n  -- its refusal marker (`linger_refused`).\n  pfn unregister_role(node : Cap(ClusterNode.Live), me : String, fingerprint : String) : () do\n    ClusterNode.unregister(node, me)\n    if fingerprint == \"\" do ()\n    else\n      ClusterNode.unregister(node, me ++ \"#\" ++ fingerprint)\n      ClusterNode.unregister(node, me ++ \"!refused\")\n    end\n  end\n\n  -- Having refused role [r] on its fingerprint, keep this role's names for\n  -- up to [left] ms before tearing down, so that [r] finds them and makes\n  -- the same check. Without it, a party that found its peer first refused\n  -- and unregistered before the peer's registry ever showed it, and the\n  -- peer waited out `find_peers`' 30 s for \"no endpoint registered\" instead\n  -- of reporting the skew. \"<me>!refused\" says this role has refused: the\n  -- peer, refusing in turn, stops waiting the moment it sees it, so two\n  -- checking parties do not each wait out the other. Ends early once [r]'s\n  -- role name is gone (it refused and left) or [r] has refused too.\n  pfn linger_refused(node : Cap(ClusterNode.Live), p : Party, me : String, session : String, r : Int, left : Int) : () do\n    let _ = ClusterNode.register(node, me ++ \"!refused\", p.ep)\n    linger_wait(node, role_name(session, r), left)\n  end\n\n  pfn linger_wait(node : Cap(ClusterNode.Live), peer : String, left : Int) : () do\n    if left <= 0 do ()\n    else if Option.is_none(ClusterNode.lookup(node, peer)) do ()\n    else if Option.is_some(ClusterNode.lookup(node, peer ++ \"!refused\")) do ()\n    else\n      sleep_ms(50)\n      linger_wait(node, peer, left - 50)\n    end end end\n  end\n\n  -- Report [role] ended to the endpoint actor, once.\n  pfn link_ended(p : Party, role : Int, why : String) : () do\n    let key = \"link_done\" ++ rkey(role)\n    if Vault.get(p.meta, key) != None do () else\n      Vault.set(p.meta, key, 1)\n      let _ = send(p.ep, LinkEnded(role, why))\n      ()\n    end\n  end\n\n  pfn cluster_kind(p : Party, kind : String, payload : List(Int)) : Result((), String) do\n    if kind == \"SessionNode.Deliver\" do\n      match decode_deliver_flag(payload) do\n        Err(e) -> Err(e)\n        Ok((to, from, msg, draining)) ->\n          let _ = if draining do send(p.ep, DeliverDraining(p, to, from, msg)) else send(p.ep, Deliver(p, to, from, msg)) end\n          Ok(())\n      end\n    else if kind == \"SessionNode.Undelivered\" do\n      match decode_deliver(payload) do\n        Err(e) -> Err(e)\n        Ok((_to, from, msg)) ->\n          let _ = send(p.ep, Returned(p, from, msg))\n          Ok(())\n      end\n    else if kind == \"SessionNode.Drained\" do\n      match decode_role(payload) do\n        Err(e) -> Err(e)\n        Ok(role) ->\n          let _ = send(p.ep, PeerGone(p, role, \"drained\"))\n          Ok(())\n      end\n    else if kind == \"SessionNode.Bye\" do\n      match Msgpack.decode(payload) do\n        Ok(Msgpack.Int(role)) ->\n          let _ = send(p.ep, PeerGone(p, role, \"closed\"))\n          link_ended(p, role, \"\")\n          Ok(())\n        _ -> Err(\"session_node: bad Bye payload\")\n      end\n    else if kind == \"SessionNode.Cancel\" do\n      match decode_cancel(payload) do\n        Err(e) -> Err(e)\n        Ok((role, cause)) ->\n          let _ = send(p.ep, PeerGone(p, role, cause))\n          link_ended(p, role, \"\")\n          Ok(())\n      end\n    else if kind == \"SessionNode.Ping\" do\n      Ok(())\n    else\n      Err(\"session_node: unexpected type \" ++ kind)\n    end end end end end end\n  end\n\n  -- `cluster_kind`, run in the endpoint actor's own turn (`Early`, `Ready`):\n  -- a held frame is handled HERE rather than re-sent to this mailbox, where\n  -- it would land behind frames the reader forwarded after it.\n  pfn cluster_kind_here(p : Party, kind : String, payload : List(Int)) : Result((), String) do\n    if kind == \"SessionNode.Deliver\" do\n      match decode_deliver_flag(payload) do\n        Err(e) -> Err(e)\n        Ok((to, from, msg, draining)) ->\n          if draining do Vault.set(p.meta, \"sdrain\" ++ rkey(from), 1) else () end\n          let _ = deliver(p, to, from, msg)\n          Ok(())\n      end\n    else if kind == \"SessionNode.Undelivered\" do\n      match decode_deliver(payload) do\n        Err(e) -> Err(e)\n        Ok((_to, from, msg)) ->\n          record_undelivered(p, from, msg)\n          peer_gone(p, from, \"drained\")\n          Ok(())\n      end\n    else if kind == \"SessionNode.Drained\" do\n      match decode_role(payload) do\n        Err(e) -> Err(e)\n        Ok(role) ->\n          peer_gone(p, role, \"drained\")\n          Ok(())\n      end\n    else if kind == \"SessionNode.Bye\" do\n      match Msgpack.decode(payload) do\n        Ok(Msgpack.Int(role)) ->\n          peer_gone(p, role, \"closed\")\n          link_ended(p, role, \"\")\n          Ok(())\n        _ -> Err(\"session_node: bad Bye payload\")\n      end\n    else if kind == \"SessionNode.Cancel\" do\n      match decode_cancel(payload) do\n        Err(e) -> Err(e)\n        Ok((role, cause)) ->\n          peer_gone(p, role, cause)\n          link_ended(p, role, \"\")\n          Ok(())\n      end\n    else Ok(()) end end end end end\n  end\n\n  -- The frame kinds a session receives, as a small number to hold an early\n  -- frame by (`Early`), and back.\n  pfn early_kind(kind : String) : Int do\n    if kind == \"SessionNode.Deliver\" do 1\n    else if kind == \"SessionNode.Bye\" do 2\n    else if kind == \"SessionNode.Cancel\" do 3\n    else if kind == \"SessionNode.Ping\" do 4\n    else if kind == \"SessionNode.Undelivered\" do 5\n    else if kind == \"SessionNode.Drained\" do 6\n    else 0 end end end end end end\n  end\n\n  pfn early_kind_name(k : Int) : String do\n    if k == 1 do \"SessionNode.Deliver\"\n    else if k == 2 do \"SessionNode.Bye\"\n    else if k == 3 do \"SessionNode.Cancel\"\n    else if k == 5 do \"SessionNode.Undelivered\"\n    else if k == 6 do \"SessionNode.Drained\"\n    else \"SessionNode.Ping\" end end end end end\n  end\n\n  -- A frame for this session, from the node's data reader -- a task every\n  -- session and route on that peer connection shares, so it must never\n  -- wait. Before the session is ready (a peer can send as soon as it has\n  -- found us, which may be before we have found it), the frame goes to the\n  -- session's endpoint actor, which holds it until `Ready` (see `Early`).\n  -- Until 2026-09-19 the reader polled for the session instead, up to 10 s,\n  -- holding up every other session's frames on that connection meanwhile.\n  pfn cluster_frame(slot : Vault(Party), p0 : Party, sid : String, d : NodeSend.Delivery) : Result((), String) do\n    match String.split_first(d.type_tag, \"#\") do\n      None -> Err(\"session_node: untagged frame \" ++ d.type_tag ++ \" for cluster session \" ++ sid)\n      Some((kind, fsid)) ->\n        if fsid != sid do\n          Err(\"session_node: frame for session \" ++ fsid ++ \", this endpoint is in session \" ++ sid)\n        else if early_kind(kind) == 0 do\n          Err(\"session_node: unexpected type \" ++ kind)\n        else\n          match Vault.get(slot, \"p\") do\n            Some(p) ->\n              if Vault.get(p.meta, \"ready\") != None do cluster_kind(p, kind, d.payload)\n              else\n                let _ = send(p0.ep, Early(slot, p0, early_kind(kind), Bytes.from_list(d.payload)))\n                Ok(())\n              end\n            None ->\n              let _ = send(p0.ep, Early(slot, p0, early_kind(kind), Bytes.from_list(d.payload)))\n              Ok(())\n          end\n        end end\n    end\n  end\n\n  -- The node of every role on [node_id] ended its data connection: each is\n  -- gone for [why] (\"node <name> dead: <cause>\", \"connection lost\", ...).\n  --\n  -- The connection is the node's, not the peer's: the peer's node may\n  -- redial at once, and the peer's party may be on the pair that survives\n  -- (two crossed dials: the pair this node installed first lost to the\n  -- other, `ClusterNode.keeps_new`, while the peer's node never installed\n  -- it), so it hears nothing of this close. Whatever this role sent on the\n  -- old pair may be lost, so the session cannot go on with that peer:\n  -- unless that peer had already ended, tell it, over the node's next pair\n  -- to its node (`notify_redialled`), that this role is cancelled for it.\n  -- Without this the peer waited on a lost frame, or for this role's Bye,\n  -- for ever (specs/progress/2026-10-12-session-redial-hang.md).\n  pfn peer_node_closed(node : Cap(ClusterNode.Live), p : Party, node_id : String, why : String) : () do\n    let _ = List.map(p.links, fn l ->\n      if l.peer.node_id == node_id do\n        if Vault.get(p.gone, rkey(l.role)) == None do\n          notify_redialled(node, l, wire_seq(p.meta), wire_tag(p, \"SessionNode.Cancel\"),\n                           encode_cancel(p.my_role, \"role \" ++ int_to_string(p.my_role) ++ \"'s node lost its connection: \" ++ why),\n                           connect_ms())\n        else () end\n        let _ = send(p.ep, PeerGone(p, l.role, why))\n        link_ended(p, l.role, why)\n      else () end)\n    ()\n  end\n\n  -- Cast [payload] to [l]'s peer once its node has a pair other than\n  -- [l]'s (a redial, or the duplicate that replaced it), waiting up to\n  -- [left] ms for one. A task of its own: the caller is a data reader,\n  -- which must never wait, and it touches none of the party's tables, which\n  -- may be closed by the time it sends. No new pair within [left]: the peer's\n  -- node is gone, or cut off, and its own reader ends its party's link.\n  pfn notify_redialled(node : Cap(ClusterNode.Live), l : Link, seq : Int, tag : String, payload : List(Int), left : Int) : () do\n    let old = match l.q do (w, _) -> pid_to_int(w) end\n    let peer = l.peer\n    let _ = task_spawn(fn _ -> await_redial(node, old, peer, seq, tag, payload, left))\n    ()\n  end\n\n  pfn await_redial(node : Cap(ClusterNode.Live), old : Int, peer : GlobalPid.Pid, seq : Int, tag : String,\n                   payload : List(Int), left : Int) : Int do\n    let fresh = match ClusterNode.session_queue_for(node, peer.node_id) do\n      Some((w, fd)) -> if pid_to_int(w) != old do Some((w, fd)) else None end\n      None -> None\n    end\n    match fresh do\n      Some(q) ->\n        let _ = NodeQueue.cast(q, seq, peer, tag, payload, NodeQueue.Unbounded)\n        0\n      None ->\n        if left <= 0 do 0 else\n          sleep_ms(50)\n          await_redial(node, old, peer, seq, tag, payload, left - 50)\n        end\n    end\n  end\n\n  pfn slot_peer_closed(node : Cap(ClusterNode.Live), slot : Vault(Party), node_id : String, why : String) : () do\n    match Vault.get(slot, \"p\") do\n      Some(p) -> peer_node_closed(node, p, node_id, why)\n      None -> ()\n    end\n  end\n\n  -- The node of [node_id] refused one of this party's frames ([reason]: no\n  -- route, as its endpoint is gone; a stale creation; not authorized): the\n  -- frame is lost, so every role on that node is gone for this party, as if\n  -- its connection had ended. Before 2026-10-12 nobody read a session\n  -- frame's DELIVERY_FAILED, and a peer that was waiting on the lost frame\n  -- (or on a reply to it) waited for ever. Runs in a control reader's turn:\n  -- it only sends.\n  pfn slot_refused(slot : Vault(Party), node_id : String, reason : String) : () do\n    match Vault.get(slot, \"p\") do\n      None -> ()\n      Some(p) ->\n        let why = \"frame refused by node \" ++ node_id ++ \": \" ++ reason\n        let _ = List.map(p.links, fn l ->\n          if l.peer.node_id == node_id do\n            let _ = send(p.ep, PeerGone(p, l.role, why))\n            link_ended(p, l.role, why)\n          else () end)\n        ()\n    end\n  end\n\n  pfn recheck_links(node : Cap(ClusterNode.Live), p : Party) : () do\n    let _ = List.map(p.links, fn l -> do\n      let current = match ClusterNode.session_queue_for(node, l.peer.node_id) do\n        Some((w, _)) -> match l.q do (lw, _) -> pid_to_int(w) == pid_to_int(lw) end\n        None -> false\n      end\n      if current do () else peer_node_closed(node, p, l.peer.node_id, \"connection lost before the session formed\") end\n    end)\n    ()\n  end\n\n  -- Each peer role's endpoint, by name; waits up to [left] ms for all of them,\n  -- or until [abandoned] says the session was withdrawn (an access point's\n  -- session whose initiator gave up on it): Err((0, found)) then, else\n  -- Err((a missing role, found)), [found] being the peers found so far.\n  pfn find_peers(node : Cap(ClusterNode.Live), session : String, peers : List(Int), left : Int,\n                 abandoned : Int -> Bool) : Result(List((Int, GlobalPid.Pid)), (Int, List((Int, GlobalPid.Pid)))) do\n    let found = List.map(peers, fn r -> (r, ClusterNode.lookup(node, role_name(session, r))))\n    let some = List.filter_map(found, fn rp ->\n      match rp do\n        (r, Some(g)) -> Some((r, g))\n        (_, None) -> None\n      end)\n    match List.find(found, fn rp -> match rp do (_r, o) -> Option.is_none(o) end) do\n      None -> Ok(some)\n      Some((missing, _)) ->\n        if abandoned(0) do Err((0, some))\n        else if left <= 0 do Err((missing, some)) else\n          sleep_ms(50)\n          find_peers(node, session, peers, left - 50, abandoned)\n        end end\n    end\n  end\n\n  -- A Link per peer over the node's data queue to that peer's node; waits\n  -- up to [left] ms for each node to be linked.\n  pfn cluster_links(node : Cap(ClusterNode.Live), found : List((Int, GlobalPid.Pid)), left : Int)\n      : Result(List(Link), Int) do\n    let qs = List.map(found, fn rg ->\n      match rg do (r, g) -> (r, g, ClusterNode.session_queue_for(node, g.node_id)) end)\n    match List.find(qs, fn t -> match t do (_r, _g, q) -> Option.is_none(q) end) do\n      None ->\n        Ok(List.filter_map(qs, fn t ->\n          match t do\n            (r, g, Some(q)) -> Some({ role: r, data_fd: -1, control_fd: -1, peer: g, q: q,\n                                      control: task_spawn(fn _ -> 0) })\n            _ -> None\n          end))\n      Some((missing, g, _)) ->\n        -- A peer on a node SWIM has declared dead never links: give up now\n        -- rather than at [left]. A session whose initiator's node died\n        -- while it formed otherwise held its offer's slot for the whole\n        -- 30 s, and kept that node's own SIGTERM drain from finishing.\n        if left <= 0 || node_dead(node, g.node_id) do Err(missing) else\n          sleep_ms(50)\n          cluster_links(node, found, left - 50)\n        end\n    end\n  end\n\n  pfn node_dead(node : Cap(ClusterNode.Live), node_id : String) : Bool do\n    List.any(ClusterNode.all_members(node), fn m ->\n      m.node_id == node_id && (match m.status do\n        Membership.Dead -> true\n        _ -> false\n      end))\n  end\n\n  -- This party gives up before it formed (a peer never registered, a\n  -- holder failed its check, or a peer's node never linked) after\n  -- registering its endpoint, so the peers in [found] may have found it and\n  -- formed: send each one this node has a link to a Cancel for our role, as\n  -- `cancel_endpoint` would once formed. It reaches the peer's endpoint like\n  -- any frame (held until that party is ready), so a peer that waits on\n  -- this role fails rather than waiting for ever. A peer on a node this one\n  -- has no link to yet is not told; it fails when its own setup gives up\n  -- (it cannot find this role's name once it is unregistered), and tells\n  -- ITS found peers in turn.\n  pfn abandon_found(node : Cap(ClusterNode.Live), p0 : Party, found : List((Int, GlobalPid.Pid)), cause : String) : () do\n    List.each(found, fn rg -> match rg do\n      (_r, g) ->\n        match ClusterNode.session_queue_for(node, g.node_id) do\n          Some(q) ->\n            let _ = NodeQueue.cast(q, wire_seq(p0.meta), g, wire_tag(p0, \"SessionNode.Cancel\"),\n                                   encode_cancel(p0.my_role, cause), NodeQueue.Unbounded)\n            ()\n          None -> ()\n        end\n    end)\n  end\n\n  -- No check on who holds a role's name: `run_cluster` (the caller chose\n  -- the session id and its members) and every shared-secret node.\n  pfn no_holder_check(_r : Int, _node_id : String) : Result((), String) do Ok(()) end\n\n  -- Every found role's holder passes [holder_ok], or Err((role, why)).\n  pfn check_holders(found : List((Int, GlobalPid.Pid)), holder_ok : Int -> String -> Result((), String))\n      : Result((), (Int, String)) do\n    match found do\n      Nil -> Ok(())\n      Cons((r, g), rest) ->\n        match holder_ok(r, g.node_id) do\n          Ok(_) -> check_holders(rest, holder_ok)\n          Err(why) -> Err((r, why))\n        end\n    end\n  end\n\n  -- The process-wide counter a cluster party's seq key comes from\n  -- (`ClusterNode.session_seq`): never reused, so a late DELIVERY_FAILED for\n  -- an ended session's frame finds no handler rather than another session's.\n  pfn session_keys() : Vault(Int) do Vault.open(\"session_node_seq_keys\") end\n\n  -- A cluster party's end: its tables and its route's slot. Runs once the\n  -- route is gone, so no frame reaches the slot after.\n  pfn close_cluster_party(p : Party, slot : Vault(Party)) : () do\n    Vault.close(slot)\n    close_party(p)\n  end\n\n  pfn serve_cluster_outcome(p : Party) : () do\n    let _ = send(p.ep, Expect(List.length(p.links)))\n    let _ = await_outcome(p)\n    await_hosted_end(p, connect_ms())\n    if ep_done(p) do () else\n      match Vault.get(p.meta, \"ep\") do\n        Some(ep) -> cancel_endpoint(p, ep, 0, \"every peer is gone\", \"every peer is gone\", kind_cancelled())\n        None -> Vault.set(p.meta, \"done\", 1)\n      end\n    end\n  end\n\n  -- Every peer has ended, but a HOSTED endpoint's last step runs in its\n  -- host actor's turn, not the endpoint actor's: the delivery that lets it\n  -- finish (Ledger's last `skip`, say) can be forwarded to the host just\n  -- before the peers' Byes end their links here. Give the host up to\n  -- [left] ms to close (or to suspend on a role that is gone, which\n  -- cancels it in the endpoint actor's turn) before the runner cancels it\n  -- itself and tears the party down: torn down first, the host's own Byes\n  -- found the session's tables closed, went out untagged and were refused,\n  -- and a peer still waiting on them hung (cert_order, round 2). A\n  -- callback-API party needs no wait: its continuations run in the\n  -- endpoint actor, ahead of the `LinkEnded` that settled the outcome.\n  pfn await_hosted_end(p : Party, left : Int) : () do\n    if ep_done(p) || left <= 0 do ()\n    else\n      match Vault.get(p.forward, \"f\") do\n        None -> ()\n        Some(_) ->\n          sleep_ms(10)\n          await_hosted_end(p, left - 10)\n      end\n    end\n  end\n\n  -- A session that did not fail: `Drained(n)` if our endpoint drained or\n  -- [n] > 0 of our messages came back undelivered (D27), else `Finished`.\n  pfn outcome_of(p : Party) : Session.Outcome do\n    let n = Vault.get_or(p.meta, \"undelivered\", 0)\n    if drained_here(p) || n > 0 do Session.Drained(n) else Session.Finished end\n  end\n\n  pfn run_result(p : Party, my_role : Int) : Result(Session.Outcome, RunError) do\n    let role = Vault.get_or(p.meta, \"cancel_role\", 0)\n    let cause = Vault.get_or(p.why, \"cancel_cause\", \"\")\n    match Vault.get(p.meta, \"kind\") do\n      None -> Ok(outcome_of(p))\n      Some(kind) ->\n        if kind == kind_protocol() do Err(Protocol(role, cause))\n        else if kind == kind_host_gone() do Err(HostGone(Vault.get_or(p.meta, \"ep\", my_role)))\n        else if kind == kind_left() do Err(RunError.Left(cause))\n        else Err(Cancelled(role, cause)) end end end\n    end\n  end\n\n  doc \"\"\"\n  `run`, over the running cluster node [node] (ClusterNode.start) instead of\n  connections of its own: role [my_role] of session [session] (any string\n  the roles agree on -- a fresh one per session). Each role registers its\n  endpoint under the session's name and finds its peers' by name (waiting up\n  to 30 s), then [body] drives it exactly as for `run`. A peer is gone when\n  it closes or is cancelled, or when its node's data connection ends --\n  SWIM declared the node dead (\"node <name> dead: <cause>\") or the\n  connection was lost. Every role must be on a different node.\n\n  [fingerprint] is the protocol's (`<P>_Msg.role_fingerprint(role)`): each\n  role registers it beside its endpoint, and a peer that registered a\n  different one, or none (a node built before the check), is refused with\n  `Err(Connect(role, why))` before the session forms, as the direct runner\n  refuses it at the hello. `\"\"` checks nothing. The generated\n  `<P>_Run.cluster_<Role>` supplies the role, its peers and the fingerprint.\n  \"\"\"\n  fn run_cluster(io : Cap(IO), node : Cap(ClusterNode.Live), my_role : Int, peers : List(Int), session : String,\n                 fingerprint : String, on_close : Int -> Unit, body : Cap(Session.Live) -> Unit)\n      : Result(Session.Outcome, RunError) do\n    counted(node, fn () ->\n      run_cluster_party(io, node, my_role, peers, session, fingerprint, on_close, fn (_p, s) -> body(s), fn _ -> false,\n                        no_holder_check))\n  end\n\n  doc \"\"\"\n  How many sessions [node] is running that no offer counts: those\n  `initiate`, `run_cluster` and `run_cluster_hosted` calls on this node\n  have started and not yet returned from (an offer's sessions are its\n  `OfferCount.active`). `Topology`'s SIGTERM drain waits for both.\n  \"\"\"\n  fn initiated(node : Cap(ClusterNode.Live)) : Int do\n    Vault.get_or(initiated_table(node), \"n\", 0)\n  end\n\n  doc \"\"\"\n  From now on, every `initiate` on [node] is refused with\n  `Err(Left(\"draining\"))` before it invites anyone: the node is draining\n  (`Topology`'s SIGTERM drain calls it), so a task that keeps starting\n  sessions -- a pool hook's traffic loop -- cannot keep the drain from ever\n  seeing zero sessions. Sessions already started run on. Permanent for the\n  node.\n  \"\"\"\n  fn refuse_initiations(node : Cap(ClusterNode.Live)) : () do\n    Vault.set(initiated_table(node), \"refuse\", 1)\n  end\n\n  doc \"Has `refuse_initiations` been called for [node]?\"\n  fn refusing_initiations(node : Cap(ClusterNode.Live)) : Bool do\n    Vault.get(initiated_table(node), \"refuse\") != None\n  end\n\n  pfn initiated_table(node : Cap(ClusterNode.Live)) : Vault(Int) do\n    Vault.open(\"session_node_initiated_\" ++ ClusterNode.node_id(node))\n  end\n\n  -- Run [f] (one session this node started) counted in `initiated`.\n  pfn counted(node : Cap(ClusterNode.Live), f : () -> a) : a do\n    let t = initiated_table(node)\n    let _ = Vault.incr(t, \"n\", 1)\n    let r = f()\n    let _ = Vault.incr(t, \"n\", 0 - 1)\n    r\n  end\n\n  -- `run_cluster`, abandoned while still finding its peers once [abandoned]\n  -- says so (an access point's session the initiator withdrew).\n  pfn run_cluster_with(io : Cap(IO), node : Cap(ClusterNode.Live), my_role : Int, peers : List(Int), session : String,\n                       on_close : Int -> Unit, body : Cap(Session.Live) -> Unit, abandoned : Int -> Bool,\n                       holder_ok : Int -> String -> Result((), String)) : Result(Session.Outcome, RunError) do\n    run_cluster_party(io, node, my_role, peers, session, \"\", on_close, fn (_p, s) -> body(s), abandoned, holder_ok)\n  end\n\n  doc \"\"\"\n  `run_cluster`, with the role HOSTED IN AN ACTOR [host] (its pid as an Int),\n  as `run_hosted_or` hosts it over the runner's own connections: [start]\n  gets the session capability once the party is formed, [deliver] every\n  delivery the actor's parked endpoint awaits, `(s, from, msg, ep)`, and\n  [cancel] a cancellation, `(s, role, cause, ep)`. The host is monitored:\n  its `Down` ends the session with `Err(HostGone(ep))`. The generated\n  `<P>_Run.cluster_hosted_<Role>` supplies the role and its peers and adds\n  the session id to every callback. [fingerprint] is checked as for\n  `run_cluster`.\n  \"\"\"\n  fn run_cluster_hosted(io : Cap(IO), node : Cap(ClusterNode.Live), my_role : Int, peers : List(Int), session : String,\n                        fingerprint : String, on_close : Int -> Unit, host : Int, start : Cap(Session.Live) -> Unit,\n                        deliver : Cap(Session.Live) -> Int -> Bytes -> Int -> Unit,\n                        cancel : Cap(Session.Live) -> Int -> String -> Int -> Unit) : Result(Session.Outcome, RunError) do\n    counted(node, fn () ->\n      run_cluster_party(io, node, my_role, peers, session, fingerprint, on_close,\n                        fn (p, s) -> host_party(p, s, host, start, deliver, cancel), fn _ -> false, no_holder_check))\n  end\n\n  -- `run_cluster_hosted`, abandoned while still finding its peers once\n  -- [abandoned] says so (a hosted access point's session the initiator\n  -- withdrew).\n  pfn run_cluster_hosted_with(io : Cap(IO), node : Cap(ClusterNode.Live), my_role : Int, peers : List(Int), session : String,\n                              on_close : Int -> Unit, host : Int, start : Cap(Session.Live) -> Unit,\n                              deliver : Cap(Session.Live) -> Int -> Bytes -> Int -> Unit,\n                              cancel : Cap(Session.Live) -> Int -> String -> Int -> Unit,\n                              abandoned : Int -> Bool, holder_ok : Int -> String -> Result((), String))\n      : Result(Session.Outcome, RunError) do\n    run_cluster_party(io, node, my_role, peers, session, \"\", on_close,\n                      fn (p, s) -> host_party(p, s, host, start, deliver, cancel), abandoned, holder_ok)\n  end\n\n  -- The cluster runner proper: form the party under [session], then [drive]\n  -- it (a callback body, or a hosted party's setup) and serve it to its end.\n  pfn run_cluster_party(io : Cap(IO), node : Cap(ClusterNode.Live), my_role : Int, peers : List(Int), session : String,\n                        fingerprint : String, on_close : Int -> Unit, drive : Party -> Cap(Session.Live) -> Unit,\n                        abandoned : Int -> Bool, holder_ok : Int -> String -> Result((), String))\n      : Result(Session.Outcome, RunError) do\n    let p0 = party(my_role, ClusterNode.node_id(node), on_close)\n    Vault.set(p0.why, \"sid\", session)\n    let slot = Vault.new(\"session_node_slot_\" ++ session ++ \".\" ++ int_to_string(pid_to_int(p0.ep)))\n    let route_key = ClusterNode.route_session(node, pid_to_int(p0.ep), fn d -> cluster_frame(slot, p0, session, d))\n    let me = role_name(session, my_role)\n    let fp_ok = if fingerprint == \"\" do Ok(())\n                else ClusterNode.register(node, fingerprint_name(session, my_role, fingerprint), p0.ep) end\n    let registered = match fp_ok do\n      Err(e) -> Err(e)\n      Ok(_) ->\n        match ClusterNode.register(node, me, p0.ep) do\n          Err(e) ->\n            if fingerprint == \"\" do () else ClusterNode.unregister(node, fingerprint_name(session, my_role, fingerprint)) end\n            Err(e)\n          Ok(u) -> Ok(u)\n        end\n    end\n    match registered do\n      Err(_) ->\n        ClusterNode.unroute(node, route_key)\n        end_party(p0)\n        close_cluster_party(p0, slot)\n        Err(Listen(my_role, \"session \" ++ session ++ \": role \" ++ int_to_string(my_role) ++ \" is already registered\"))\n      Ok(_) ->\n        -- This party's frames go out under its own seq key, so a peer's\n        -- node that refuses one tells this party (`slot_refused`).\n        let skey = Vault.incr(session_keys(), \"n\", 1)\n        Vault.set(p0.meta, \"skey\", skey)\n        ClusterNode.on_session_failed(node, skey, fn (nid, reason) -> slot_refused(slot, nid, reason))\n        match find_peers(node, session, peers, 30000, abandoned) do\n          Err((missing, found_some)) ->\n            -- The peers found so far may have found us too, and formed.\n            abandon_found(node, p0, found_some,\n                          \"session \" ++ session ++ \": \" ++ (if missing == 0 do \"withdrawn by its initiator\"\n                                                            else \"no endpoint registered for role \" ++ int_to_string(missing) end))\n            ClusterNode.unroute(node, route_key)\n            unregister_role(node, me, fingerprint)\n            ClusterNode.off_session_failed(node, skey)\n            end_party(p0)\n            close_cluster_party(p0, slot)\n            if missing == 0 do Err(RunError.Connect(0, \"session \" ++ session ++ \": withdrawn by its initiator\"))\n            else Err(RunError.Connect(missing, \"session \" ++ session ++ \": no endpoint registered for role \" ++ int_to_string(missing))) end\n          Ok(found0) ->\n            -- A role's endpoint is found by a registry name any member can\n            -- write: an access point's session checks the certificate of\n            -- the node holding each one (step 11b; `holder_ok`). Only once\n            -- every holder's node is LINKED: a peer's certificate is known\n            -- from its link's handshake, and a peer found through the\n            -- registry (gossip, via a third node) may not be linked yet.\n            -- Checked first, it failed as \"presented no certificate\" while\n            -- the peers that had already found this endpoint formed and\n            -- waited on it for ever (specs/progress/2026-10-12-cert-mode-\n            -- offer-to-offer-session-hang.md).\n            -- The protocol fingerprint first: a peer from another version of\n            -- the protocol is refused before anything is linked or sent.\n            let linked = match check_peer_fingerprints(node, session, found0, fingerprint, 2000) do\n              Err((r, why)) ->\n                linger_refused(node, p0, me, session, r, 2000)\n                Err((r, why))\n              Ok(_) ->\n                match cluster_links(node, found0, 30000) do\n                  Err(missing) -> Err((missing, \"no link to role \" ++ int_to_string(missing) ++ \"'s node\"))\n                  Ok(ls) ->\n                    match check_holders(found0, holder_ok) do\n                      Err(e) -> Err(e)\n                      Ok(_) -> Ok(ls)\n                    end\n                end\n            end\n            match linked do\n              Err((missing, why)) ->\n                -- The peers found us and may have formed: tell each it can\n                -- reach that this role is cancelled, or one waiting on it\n                -- would wait for ever.\n                abandon_found(node, p0, found0, \"session \" ++ session ++ \": \" ++ why)\n                ClusterNode.unroute(node, route_key)\n                unregister_role(node, me, fingerprint)\n                ClusterNode.off_session_failed(node, skey)\n                end_party(p0)\n                close_cluster_party(p0, slot)\n                Err(RunError.Connect(missing, \"session \" ++ session ++ \": \" ++ why))\n              Ok(links) ->\n                let p = List.fold_left(links, p0, fn (acc, l) -> with_link(acc, l))\n                Vault.set(slot, \"p\", p)\n                let closer = ClusterNode.on_peer_closed(node, fn (nid, why) -> slot_peer_closed(node, slot, nid, why))\n                -- A peer's node whose connection ended between finding it and\n                -- installing the handler above was told to nobody: check now\n                -- that every link is still the node's current one. (Reported\n                -- twice is harmless: the first PeerGone wins, LinkEnded is once.)\n                recheck_links(node, p)\n                let o = ops(p)\n                let s = Session.attach(io, o)\n                drive(p, s)\n                -- Only now, with the role driven to its first suspension and\n                -- its first handler installed, are held frames replayed (and\n                -- later ones handled as they come): one handled earlier would\n                -- find no handler and be parked where, in the callback API,\n                -- nothing drains it -- the session would wait for ever (the\n                -- standalone runner starts its readers after the drive for\n                -- the same reason). A hosted party may not have parked yet\n                -- when this is sent: its start message is in the actor's\n                -- mailbox; a frame replayed before the actor parks is held,\n                -- and the park's `Drain` finds it.\n                let _ = send(p.ep, Ready(p))\n                serve_cluster_outcome(p)\n                stop_host_watch(p)\n                ClusterNode.off_peer_closed(node, closer)\n                ClusterNode.off_session_failed(node, skey)\n                ClusterNode.unroute(node, route_key)\n                unregister_role(node, me, fingerprint)\n                end_party(p)\n                let r = run_result(p, my_role)\n                close_cluster_party(p, slot)\n                retire_ops(o)\n                r\n            end\n        end\n    end\n  end\n\n  -- \u2500\u2500 access points \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- A node OFFERS a role of a protocol for many sessions; a session forms when\n  -- an INITIATOR invites one offer of each other role, found by name, and\n  -- every member runs the cluster session under a fresh id. Design:\n  -- specs/2026-09-19-choreography-access-points-and-crash-branches-design.md\n  -- (Part A). Wire, over the cluster node (routed by the offer's / the\n  -- initiator's inbox pid):\n  --   SessionAP.Invite    [sid, fingerprint, reply pid, initiator role, vouch]\n  --                                                       initiator -> offer\n  --     (the last two optional: a 3-element Invite from an older node still\n  --     decodes, its role -1, refused in certificate mode; [vouch] lists the\n  --     offer fingerprints a NEWER initiator has checked against its own\n  --     compatibility table, step 9; the initiator's role is what the offer\n  --     checks its certificate against, step 11b)\n  --   SessionAP.Withdraw  [sid]                           initiator -> offer\n  --   SessionAP.Answer    [sid, node_id, verdict]         offer -> initiator\n  -- where verdict \"\" accepts and anything else is why it refused.\n\n  -- An offer's name: one per protocol, role, FINGERPRINT and node\n  -- (`ap:<P>/<role>/<fp>/<node>`, build step 9), so two versions of one role\n  -- can be offered side by side on a node and an initiator can tell an\n  -- offer's version from its name, before inviting it.\n  pfn ap_prefix(proto : String, role : Int) : String do\n    \"ap:\" ++ proto ++ \"/\" ++ int_to_string(role) ++ \"/\"\n  end\n\n  pfn ap_name(proto : String, role : Int, fp : String, node_id : String) : String do\n    ap_prefix(proto, role) ++ fp ++ \"/\" ++ node_id\n  end\n\n  doc \"\"\"\n  The fingerprint in an offer's registry name [name] (after [prefix], the\n  protocol and role part), or `\"\"` for a name in the older form\n  `ap:<P>/<role>/<node>`, which carried none.\n  \"\"\"\n  fn name_fingerprint(prefix : String, name : String) : String do\n    let pl = String.byte_size(prefix)\n    let rest = String.slice(name, pl, String.byte_size(name) - pl)\n    match String.index_of(rest, \"/\") do\n      Some(i) -> String.slice(rest, 0, i)\n      None -> \"\"\n    end\n  end\n\n  -- The older fingerprints [role] accepts at this build's fingerprint: its\n  -- row of the generated `<P>_Msg.compat_by_role()` (build step 9), or none.\n  pfn accepts_of(compat : List((Int, List(String))), role : Int) : List(String) do\n    match List.find(compat, fn row -> match row do (r, _) -> r == role end) do\n      Some((_, fps)) -> fps\n      None -> Nil\n    end\n  end\n\n  type OfferCount = { active : Int }\n\n  -- An offer: what an invitation needs to be answered and its session run.\n  -- [start] runs one session under a sid, abandoned while still forming\n  -- once its argument says so. [flags] and [strs] are tables SHARED by every\n  -- offer of the process, keyed under the offer's [id] (its actor's pid):\n  -- flags \"c<id>\" (closing: 1, retiring: 2) and \"w<id>/<sid>\" for a session\n  -- its initiator withdrew, strs \"r<id>\" its route key. A Vault table is\n  -- never freed (the runtime registers it by name for the life of the\n  -- process), so two per offer were two leaked per offer opened; the keys an\n  -- offer leaves in the shared ones are dropped when its actor retires\n  -- (`retire_offer`).\n  -- [roles] is the protocol's role-name table (`<P>_Msg.role_names()`), what\n  -- the certificate checks name roles by (step 11b).\n  type Offer = { node : Cap(ClusterNode.Live), proto : String, fingerprint : String,\n                 roles : List((String, Int)), compat : List((Int, List(String))), my_role : Int,\n                 capacity : Int, name : String, id : String, flags : Vault(Int), strs : Vault(String),\n                 start : String -> (Int -> Bool) -> Result(Session.Outcome, RunError), worker : Pid(OfferCount) }\n\n  -- Whether an initiator at fingerprint [fp] may form a session with this\n  -- offer (build step 9): the same fingerprint; an OLDER one this role's row\n  -- of the compatibility table accepts (this offer is the newer side and\n  -- decides); or this offer's own fingerprint named in [vouch], the NEWER\n  -- initiator's statement that its table accepts this offer's version and it\n  -- checked every other party against it (this offer, the older side, has no\n  -- table for the newer version). Anything else is \"protocol differs\".\n  pfn fp_verdict(o : Offer, fp : String, vouch : List(String)) : String do\n    if fp == o.fingerprint do \"\"\n    else if List.member(accepts_of(o.compat, o.my_role), fp) do \"\"\n    else if List.member(vouch, o.fingerprint) do \"\"\n    else \"protocol differs\" end end end\n  end\n\n  -- \"\" accepts. [from] is the node the invitation arrived from (the link's\n  -- verified peer, `Delivery.from_node`), [irole] the role its initiator\n  -- plays (-1: an invitation that did not say).\n  pfn offer_verdict(o : Offer, active : Int, fp : String, vouch : List(String), from : String, irole : Int) : String do\n    if Vault.get(o.flags, \"c\" ++ o.id) != None do \"closing\"\n    else\n      let by_fp = fp_verdict(o, fp, vouch)\n      if by_fp != \"\" do by_fp\n      else\n        -- The certificate check (step 11b): the initiator's node must be\n        -- certified to initiate the role it plays.\n        let by_cert = initiator_verdict(o, from, irole)\n        if by_cert != \"\" do by_cert\n        else if active >= o.capacity do \"full\"\n        else \"\" end end\n      end\n    end\n  end\n\n  -- The offer's half of the two-way check (step 11b): the initiator's\n  -- certificate must name \"Proto.Role:initiate\" for the role it plays.\n  -- \"\" in shared-secret mode, and when it does.\n  pfn initiator_verdict(o : Offer, from : String, irole : Int) : String do\n    if ClusterNode.certified(o.node) == false do \"\"\n    else if irole < 0 do \"initiator \" ++ node_label(o.node, from) ++ \" did not name its role\"\n    else\n      match ClusterNode.authorize_peer(o.node, from, o.proto, SessionAP.role_name(o.roles, irole), SessionAP.initiate_mode()) do\n        Ok(_) -> \"\"\n        Err(why) -> \"initiator \" ++ node_label(o.node, from) ++ \" \" ++ why\n      end\n    end end\n  end\n\n  -- An access point's session: the node holding role [r]'s name must be one\n  -- whose certificate lets it play [r] (offer or initiate). Always Ok on a\n  -- shared-secret node.\n  pfn ap_holder_check(node : Cap(ClusterNode.Live), proto : String, roles : List((String, Int)))\n      : Int -> String -> Result((), String) do\n    fn (r, nid) ->\n      let name = SessionAP.role_name(roles, r)\n      match ClusterNode.authorize_peer(node, nid, proto, name, SessionAP.offer_mode()) do\n        Ok(_) -> Ok(())\n        Err(_) ->\n          match ClusterNode.authorize_peer(node, nid, proto, name, SessionAP.initiate_mode()) do\n            Ok(_) -> Ok(())\n            Err(why) -> Err(\"role \" ++ SessionAP.role_label(proto, name) ++ \" is held by \" ++ node_label(node, nid) ++ \": \" ++ why)\n          end\n      end\n  end\n\n  -- Invitations are answered in the offer actor's turn, so the count of\n  -- running sessions is exact; each accepted session runs in its own task\n  -- and reports back when it ends.\n  --\n  -- A closed offer's actor retires once no session runs under it (`Close`\n  -- with none running, else the last `Ended`): review finding 2026-09-25-dd-\n  -- review-offer-actors-leak, every retired offer left its actor behind. It\n  -- takes no epoch hold (each session's Endpoint takes and releases its own,\n  -- `end_party`), so ending it strands none.\n  actor OfferActor do\n    state { active : Int }\n    init  { active: 0 }\n    on Invite(o : Offer, sid : String, fp : String, vouch : List(String), reply : GlobalPid.Pid,\n              from : String, irole : Int) do\n      let verdict = offer_verdict(o, state.active, fp, vouch, from, irole)\n      let _ = ClusterNode.send_msg(o.node, reply, \"SessionAP.Answer\",\n                encode_answer(sid, ClusterNode.node_id(o.node), verdict), NodeQueue.Unbounded)\n      if verdict == \"\" do\n        let flags = o.flags\n        let start = o.start\n        let me = o.worker\n        let wkey = withdraw_key(o, sid)\n        let onode = o.node\n        -- Abandoned while still forming once the initiator withdraws it, or\n        -- once SWIM has declared the initiator's node dead: it can no longer\n        -- withdraw, and its role will never be registered, so the session\n        -- otherwise held this offer's slot for the whole 30 s peer wait\n        -- (and kept this node's SIGTERM drain from finishing).\n        let _ = task_spawn(fn _ -> do\n          let _ = start(sid, fn _ -> Vault.get(flags, wkey) != None || node_dead(onode, from))\n          let _ = Vault.delete(flags, wkey)\n          let _ = send(me, Ended(o, sid))\n          0\n        end)\n        { active: state.active + 1 }\n      else state end\n    end\n    on Withdraw(o : Offer, sid : String) do\n      Vault.set(o.flags, withdraw_key(o, sid), 1)\n      state\n    end\n    on Ended(o : Offer, _sid : String) do\n      let n = state.active - 1\n      if n <= 0 do retire_offer(o) else () end\n      { active: n }\n    end\n    on Close(o : Offer) do\n      if state.active <= 0 do retire_offer(o) else () end\n      state\n    end\n  end\n\n  pfn withdraw_key(o : Offer, sid : String) : String do \"w\" ++ o.id ++ \"/\" ++ sid end\n\n  -- In the offer actor's turn, once no session runs under [o]: if [o] is\n  -- closing (and not already retiring), end its actor and drop the keys it\n  -- left in the shared tables. The kill runs in its own task, not in this\n  -- turn; the closing flag goes only after it, so no invitation the node\n  -- still hands over in between is accepted.\n  pfn retire_offer(o : Offer) : () do\n    let ck = \"c\" ++ o.id\n    if Vault.get_or(o.flags, ck, 0) == 1 do\n      Vault.set(o.flags, ck, 2)\n      let me = o.worker\n      let flags = o.flags\n      let wprefix = \"w\" ++ o.id ++ \"/\"\n      let _ = task_spawn(fn _ -> do\n        kill(me)\n        List.each(Vault.keys(flags), fn k -> if String.starts_with(k, wprefix) do Vault.delete(flags, k) else () end)\n        Vault.delete(flags, ck)\n        0\n      end)\n      ()\n    else () end\n  end\n\n  pfn encode_invite(sid : String, fp : String, reply : GlobalPid.Pid, irole : Int, vouch : List(String)) : List(Int) do\n    Msgpack.encode(Msgpack.array(Cons(Msgpack.str(sid), Cons(Msgpack.str(fp),\n      Cons(Msgpack.bin(GlobalPid.encode(reply)), Cons(Msgpack.int(irole),\n        Cons(Msgpack.array(List.map(vouch, fn v -> Msgpack.str(v))), Nil)))))))\n  end\n\n  -- An Invite's optional fourth element: the initiator's role (-1 when an\n  -- older node sent none).\n  pfn irole_of(rest : List(Msgpack.Value)) : Int do\n    match rest do\n      Cons(Msgpack.Int(r), _) -> r\n      _ -> 0 - 1\n    end\n  end\n\n  -- An Invite's optional fifth element: the vouched fingerprints.\n  pfn vouch_of(rest : List(Msgpack.Value)) : List(String) do\n    match rest do\n      Cons(_, Cons(Msgpack.Array(vs), _)) ->\n        List.filter_map(vs, fn v ->\n          match v do\n            Msgpack.Str(x) -> Some(x)\n            _ -> None\n          end)\n      _ -> Nil\n    end\n  end\n\n  pfn encode_answer(sid : String, node_id : String, verdict : String) : List(Int) do\n    Msgpack.encode(Msgpack.array(Cons(Msgpack.str(sid), Cons(Msgpack.str(node_id), Cons(Msgpack.str(verdict), Nil)))))\n  end\n\n  pfn encode_sid(sid : String) : List(Int) do\n    Msgpack.encode(Msgpack.array(Cons(Msgpack.str(sid), Nil)))\n  end\n\n  -- An invitation or withdrawal for [o], from the node's data reader (its\n  -- turn must only send): handed to the offer actor.\n  pfn offer_frame(o : Offer, d : NodeSend.Delivery) : Result((), String) do\n    if d.type_tag == \"SessionAP.Invite\" do\n      match Msgpack.decode(d.payload) do\n        Ok(Msgpack.Array(Cons(Msgpack.Str(sid), Cons(Msgpack.Str(fp), Cons(Msgpack.Bin(rb), rest))))) ->\n          match GlobalPid.decode(rb) do\n            Ok(reply) ->\n              let _ = send(o.worker, Invite(o, sid, fp, vouch_of(rest), reply, d.from_node, irole_of(rest)))\n              Ok(())\n            Err(e) -> Err(\"session_ap: invite reply pid: \" ++ e)\n          end\n        _ -> Err(\"session_ap: bad Invite payload\")\n      end\n    else if d.type_tag == \"SessionAP.Withdraw\" do\n      match Msgpack.decode(d.payload) do\n        Ok(Msgpack.Array(Cons(Msgpack.Str(sid), Nil))) ->\n          let _ = send(o.worker, Withdraw(o, sid))\n          Ok(())\n        _ -> Err(\"session_ap: bad Withdraw payload\")\n      end\n    else Err(\"session_ap: unexpected type \" ++ d.type_tag) end end\n  end\n\n  doc \"\"\"\n  Offer role [my_role] of protocol [proto] (fingerprint [fingerprint], the\n  generated `<P>_Msg.fingerprint()`) on the cluster node [node], for up to\n  [capacity] sessions at once. Each session forms when an initiator\n  (`initiate`) invites this node; it then runs [body] in its own task, as\n  `run_cluster` would, under the session id the initiator minted. An\n  invitation is refused when the offer is full, closing, or built from a\n  version of the protocol this one cannot form a session with (build step 9:\n  the same fingerprint, or one the compatibility table [compat], the\n  generated `<P>_Msg.compat_by_role()`, relates to it), and, in certificate\n  mode, when the initiating node's certificate does not name\n  \"Proto.Role:initiate\" for the role it plays (verdict \"initiator <node>\n  not authorized for Proto.Role\"). In certificate mode this node's own\n  certificate must name \"Proto.Role:offer\" for [my_role], else\n  `Err(Unauthorized(..))`. [roles] is the protocol's role-name table\n  (step 11b). One offer per role\n  and fingerprint per node: a second is `Err`; two versions of one role may\n  be offered side by side. The generated `<P>_Run.offer_<Role>` supplies the protocol, role\n  and peers. The offer's name is bound to an actor of this node; if the\n  node stops, or a supervisor restarts the program that made it, it is\n  gone from the registry and an initiator no longer picks it -- offer again\n  to be found again.\n  \"\"\"\n  fn offer_role(io : Cap(IO), node : Cap(ClusterNode.Live), proto : String, fingerprint : String,\n           roles : List((String, Int)), compat : List((Int, List(String))), my_role : Int,\n           peers : List(Int), capacity : Int, on_close : Int -> Unit, body : Cap(Session.Live) -> Unit) : Result(Offer, RunError) do\n    let holders = ap_holder_check(node, proto, roles)\n    offer_with(node, proto, fingerprint, roles, compat, my_role, capacity,\n               fn (sid, abandoned) -> run_cluster_with(io, node, my_role, peers, sid, on_close, body, abandoned, holders))\n  end\n\n  doc \"\"\"\n  `offer_role`, with the role HOSTED IN AN ACTOR [host] (its pid as an Int)\n  for every session at once: each accepted session runs\n  `run_cluster_hosted` in its own task, and the actor keeps one parked\n  endpoint per session id (a `LinearMap`), which is why every callback\n  carries the session id: `start(sid, s)`, `deliver(sid, s, from, msg, ep)`,\n  `cancel(sid, s, role, cause, ep)`. The host is monitored once per session;\n  if it dies, every session it hosts ends with `HostGone`. The generated\n  `<P>_Run.offer_hosted_<Role>` supplies the protocol, role and peers.\n  \"\"\"\n  fn offer_hosted(io : Cap(IO), node : Cap(ClusterNode.Live), proto : String, fingerprint : String,\n                  roles : List((String, Int)), compat : List((Int, List(String))), my_role : Int,\n                  peers : List(Int), capacity : Int, on_close : Int -> Unit, host : Int,\n                  start : String -> Cap(Session.Live) -> Unit,\n                  deliver : String -> Cap(Session.Live) -> Int -> Bytes -> Int -> Unit,\n                  cancel : String -> Cap(Session.Live) -> Int -> String -> Int -> Unit) : Result(Offer, RunError) do\n    let holders = ap_holder_check(node, proto, roles)\n    let trace = hosted_trace_on()\n    let what = proto ++ \"/\" ++ int_to_string(my_role) ++ \" fp=\" ++ fingerprint ++ \" host=\" ++ int_to_string(host)\n    offer_with(node, proto, fingerprint, roles, compat, my_role, capacity, fn (sid, abandoned) ->\n      run_cluster_hosted_with(io, node, my_role, peers, sid, on_close, host,\n                              fn s -> do\n                                hosted_trace(trace, what, \"start\", sid, \"\")\n                                start(sid, s)\n                              end,\n                              fn (s, from, msg, ep) -> do\n                                hosted_trace(trace, what, \"deliver\", sid,\n                                             \"from=\" ++ int_to_string(from) ++ \" ep=\" ++ int_to_string(ep)\n                                               ++ \" bytes=\" ++ int_to_string(Bytes.length(msg)))\n                                deliver(sid, s, from, msg, ep)\n                              end,\n                              fn (s, role, cause, ep) -> do\n                                hosted_trace(trace, what, \"cancel\", sid,\n                                             \"role=\" ++ int_to_string(role) ++ \" ep=\" ++ int_to_string(ep) ++ \" cause=\" ++ cause)\n                                cancel(sid, s, role, cause, ep)\n                              end,\n                              abandoned, holders))\n  end\n\n  -- Debug trace of a hosted access point's callbacks (MARCH_SESSION_TRACE_HOSTED=1):\n  -- one stderr line per start / deliver / cancel, naming the offer (protocol,\n  -- role, fingerprint, host actor pid) and the session id, so a delivery\n  -- that reaches the wrong session or host shows up in a passing run's log.\n  -- Read once per offer; off, it prints nothing.\n  pfn hosted_trace_on() : Bool do Env.get(\"MARCH_SESSION_TRACE_HOSTED\", \"\") == \"1\" end\n\n  pfn hosted_trace(enabled : Bool, what : String, event : String, sid : String, detail : String) : () do\n    if enabled do print_stderr(\"session_node: hosted \" ++ event ++ \" \" ++ what ++ \" sid=\" ++ sid\n                          ++ (if detail == \"\" do \"\" else \" \" ++ detail end) ++ \"\\n\")\n    else () end\n  end\n\n  -- The offer itself: an actor that answers invitations and runs each\n  -- accepted session through [start] (under its sid, abandoned once the\n  -- second argument says so), routed and registered under the offer's name.\n  --\n  -- In certificate mode a node whose own certificate does not name\n  -- \"Proto.Role:offer\" does not open the offer (`Unauthorized`): every\n  -- initiator would skip it anyway (`candidates`), and this says why at the\n  -- source.\n  pfn offer_with(node : Cap(ClusterNode.Live), proto : String, fingerprint : String,\n                 roles : List((String, Int)), compat : List((Int, List(String))), my_role : Int, capacity : Int,\n                 start : String -> (Int -> Bool) -> Result(Session.Outcome, RunError)) : Result(Offer, RunError) do\n    let rname = SessionAP.role_name(roles, my_role)\n    match ClusterNode.authorize_peer(node, ClusterNode.node_id(node), proto, rname, SessionAP.offer_mode()) do\n      Err(why) -> Err(Unauthorized(my_role, \"this node \" ++ why ++ \" (its certificate lacks \"\n                                            ++ SessionAP.permission(proto, rname, SessionAP.offer_mode()) ++ \")\"))\n      Ok(_) -> open_offer(node, proto, fingerprint, roles, compat, my_role, capacity, start)\n    end\n  end\n\n  pfn open_offer(node : Cap(ClusterNode.Live), proto : String, fingerprint : String,\n                 roles : List((String, Int)), compat : List((Int, List(String))), my_role : Int, capacity : Int,\n                 start : String -> (Int -> Bool) -> Result(Session.Outcome, RunError)) : Result(Offer, RunError) do\n    let a = spawn(OfferActor)\n    let o = { node: node, proto: proto, fingerprint: fingerprint, roles: roles, compat: compat, my_role: my_role, capacity: capacity,\n              name: ap_name(proto, my_role, fingerprint, ClusterNode.node_id(node)),\n              id: int_to_string(pid_to_int(a)),\n              flags: Vault.new(\"session_ap_flags\"), strs: Vault.new(\"session_ap_strs\"),\n              start: start, worker: a }\n    let key = ClusterNode.route_session(node, pid_to_int(a), fn d -> offer_frame(o, d))\n    Vault.set(o.strs, \"r\" ++ o.id, key)\n    match ClusterNode.register(node, o.name, a) do\n      Ok(_) -> Ok(o)\n      Err(_) ->\n        -- Never registered, so nothing was invited: end the actor at once\n        -- (Topology retries a held name every placement tick, and each try\n        -- left one behind).\n        ClusterNode.unroute(node, key)\n        let _ = Vault.delete(o.strs, \"r\" ++ o.id)\n        kill(a)\n        Err(AlreadyOffered(my_role))\n    end\n  end\n\n  doc \"\"\"\n  Stop offering: new invitations are refused and the name is released.\n  Sessions already running finish; the offer's actor ends once none is left\n  (at once when none runs). Closing an offer twice is harmless.\n  \"\"\"\n  fn close_offer(o : Offer) : () do\n    let live = is_alive(o.worker)\n    if live do Vault.set(o.flags, \"c\" ++ o.id, 1) else () end\n    ClusterNode.unregister(o.node, o.name)\n    match Vault.get(o.strs, \"r\" ++ o.id) do\n      Some(k) ->\n        ClusterNode.unroute(o.node, k)\n        let _ = Vault.delete(o.strs, \"r\" ++ o.id)\n        ()\n      None -> ()\n    end\n    if live do\n      let _ = send(o.worker, Close(o))\n      ()\n    else () end\n  end\n\n  -- The initiator's reply address: an actor that exists only to have a pid\n  -- the node can route answers by.\n  actor ApInbox do\n    state { n : Int }\n    init  { n: 0 }\n    on Nop() do state end\n  end\n\n  -- Every initiation's answers, in ONE table shared by the process (keys\n  -- \"<sid>/<node id>\", `answer_key`) that is never closed. A table per\n  -- initiation, closed once its route was dropped, was freed under a data\n  -- reader still running this route for a late Answer (one that reached\n  -- the reader before the unroute): a use-after-free in `Vault.set` that the\n  -- ASan gate caught in cert_order. The keys go when the initiation ends\n  -- (`forget_answers`); one a late Answer writes after that is never read.\n  pfn answers_table() : Vault(String) do Vault.open(\"session_ap_answers\") end\n\n  pfn answer_key(sid : String, nid : String) : String do sid ++ \"/\" ++ nid end\n\n  pfn forget_answers(answers : Vault(String), sid : String) : () do\n    let prefix = sid ++ \"/\"\n    List.each(Vault.keys(answers), fn k -> if String.starts_with(k, prefix) do Vault.delete(answers, k) else () end)\n  end\n\n  pfn inbox_frame(answers : Vault(String), sid : String, d : NodeSend.Delivery) : Result((), String) do\n    if d.type_tag != \"SessionAP.Answer\" do Err(\"session_ap: unexpected type \" ++ d.type_tag)\n    else\n      match Msgpack.decode(d.payload) do\n        Ok(Msgpack.Array(Cons(Msgpack.Str(asid), Cons(Msgpack.Str(nid), Cons(Msgpack.Str(verdict), Nil))))) ->\n          if asid == sid do\n            Vault.set(answers, answer_key(sid, nid), verdict)\n            Ok(())\n          else Ok(()) end\n        _ -> Err(\"session_ap: bad Answer payload\")\n      end\n    end\n  end\n\n  -- The fingerprints already in a forming session, besides the initiator's\n  -- own: at most ONE other (build step 9). [older]: whether it is one the\n  -- initiator's table accepts (the initiator is the newer side and checks\n  -- every pair), else an unknown one taken to be newer (each such offer\n  -- checks the initiator's fingerprint itself, which covers every pair with\n  -- it, since acceptance is per newer role against the older fingerprint).\n  type ApWait = Answered(String) | OfferGone | NoAnswer\n\n  type ApMix = { fp : String, rows : List((Int, List(String))), me : Int,\n                 other : String, older : Bool, filled : List((Int, String)) }\n\n  -- Whether an offer of [role] at [ofp] may join the session [m] so far,\n  -- and the fingerprints to vouch for in its Invite.\n  pfn admissible(m : ApMix, role : Int, ofp : String) : Option(List(String)) do\n    let known_older = List.any(m.rows, fn row -> match row do (_, fps) -> List.member(fps, ofp) end)\n    if ofp == m.fp do\n      if m.other != \"\" && m.older && not(List.member(accepts_of(m.rows, role), m.other)) do None\n      else Some(Nil) end\n    else if m.other != \"\" && m.other != ofp do None\n    else if known_older do\n      -- This build is the newer side: the initiator's role and every role\n      -- already filled at its fingerprint must accept the older one.\n      let at_mine = Cons(m.me, List.filter_map(m.filled, fn f -> match f do (r, x) -> if x == m.fp do Some(r) else None end end))\n      if List.all(at_mine, fn r -> List.member(accepts_of(m.rows, r), ofp)) do Some(Cons(ofp, Nil)) else None end\n    else Some(Nil) end end end\n  end\n\n  -- The offers of [role], other than on the nodes in [used], that [m]\n  -- admits, each with what to vouch for: offers at the initiator's own\n  -- fingerprint first, then older ones the table accepts, then unknown\n  -- (possibly newer) ones -- each group with an offer on THIS node first\n  -- (prefer-local, plan 4.2: it saves a hop, and it goes over the node's\n  -- loopback link) and the rest rotated by [n] so successive sessions of one\n  -- initiator spread over them. Only offers on nodes this node is connected\n  -- to: the registry can show a name (learnt through a third node) before\n  -- the two nodes have a connection, and a session between them needs one.\n  -- Offers the table rules out are not invited at all, so no round trip is\n  -- spent on \"protocol differs\" (build step 9); the second result says how\n  -- many were skipped so, for `NoOffer`'s reason.\n  --\n  -- In certificate mode an offer is a candidate only if the node HOLDING it\n  -- (the binding's node, which is where the invitation goes) has a\n  -- certificate naming \"Proto.Role:offer\" (step 11b): offer names are\n  -- registry names any member can write, so the registry entry proves\n  -- nothing. Those skipped for it are named in the reason too.\n  pfn candidates(node : Cap(ClusterNode.Live), proto : String, names : List((String, Int)), role : Int,\n                 used : List(String), n : Int, m : ApMix)\n      : (List((GlobalPid.Pid, String, List(String))), String) do\n    let prefix = ap_prefix(proto, role)\n    let named = List.filter_map(ClusterNode.names(node), fn name ->\n      if String.starts_with(name, prefix) do\n        match ClusterNode.lookup(node, name) do\n          Some(g) -> Some((g, name_fingerprint(prefix, name)))\n          None -> None\n        end\n      else None end)\n    let found = List.filter_map(named, fn c -> match c do (g, ofp) ->\n      match admissible(m, role, ofp) do\n        Some(vouch) -> Some((g, ofp, vouch))\n        None -> None\n      end end)\n    let skipped = List.length(named) - List.length(found)\n    let why =\n      if skipped == 0 do \"\"\n      else int_to_string(skipped) ++ \" offer(s) at a protocol version this one cannot form a session with were not invited\" end\n    let linked = List.filter(found, fn c -> match c do (g, _, _) ->\n      List.member(used, g.node_id) == false && Option.is_some(ClusterNode.session_queue_for(node, g.node_id)) end)\n    let rname = SessionAP.role_name(names, role)\n    let denied = List.filter_map(linked, fn c -> match c do (g, _, _) ->\n      match ClusterNode.authorize_peer(node, g.node_id, proto, rname, SessionAP.offer_mode()) do\n        Ok(_) -> None\n        Err(e) -> Some(node_label(node, g.node_id) ++ \" \" ++ e ++ \", not invited\")\n      end end)\n    let fresh = List.filter(linked, fn c -> match c do (g, _, _) ->\n      Result.is_ok(ClusterNode.authorize_peer(node, g.node_id, proto, rname, SessionAP.offer_mode())) end)\n    let me = ClusterNode.node_id(node)\n    let group = fn cs ->\n      let local = List.filter(cs, fn c -> match c do (g, _, _) -> g.node_id == me end)\n      let remote = List.filter(cs, fn c -> match c do (g, _, _) -> g.node_id != me end)\n      let k = List.length(remote)\n      if k == 0 do local else\n        let r = n % k\n        List.append(local, List.append(List.drop(remote, r), List.take(remote, r)))\n      end\n    let same = List.filter(fresh, fn c -> match c do (_, f, _) -> f == m.fp end)\n    let vouched = List.filter(fresh, fn c -> match c do (_, f, v) -> f != m.fp && v != Nil end)\n    let unknown = List.filter(fresh, fn c -> match c do (_, f, v) -> f != m.fp && v == Nil end)\n    let reasons = List.filter(Cons(why, denied), fn x -> x != \"\")\n    (List.append(group(same), List.append(group(vouched), group(unknown))), String.join(reasons, \"; \"))\n  end\n\n  -- Wait for [nid]'s answer: Answered(verdict); OfferGone once [name] no\n  -- longer binds [g] here (the offer closed, so an invitation that reached\n  -- its node after `close_offer` dropped its route is answered by no one:\n  -- its DELIVERY_FAILED is not tied to this wait); NoAnswer once the setup\n  -- time runs out. [budget] holds the setup time left, shared by every\n  -- invitation.\n  pfn await_answer(node : Cap(ClusterNode.Live), answers : Vault(String), sid : String, g : GlobalPid.Pid, name : String,\n                   budget : Vault(Int)) : ApWait do\n    match Vault.get(answers, answer_key(sid, g.node_id)) do\n      Some(v) -> Answered(v)\n      None ->\n        if still_bound(node, name, g) == false do OfferGone\n        else if Vault.get_or(budget, \"left\", 0) <= 0 do NoAnswer else\n          sleep_ms(20)\n          let _ = Vault.incr(budget, \"left\", -20)\n          await_answer(node, answers, sid, g, name, budget)\n        end end\n    end\n  end\n\n  pfn offer_closed() : String do \"closed its offer before answering\" end\n\n  pfn still_bound(node : Cap(ClusterNode.Live), name : String, g : GlobalPid.Pid) : Bool do\n    match ClusterNode.lookup(node, name) do\n      Some(p) -> p.node_id == g.node_id && p.local_pid == g.local_pid && p.creation == g.creation\n      None -> false\n    end\n  end\n\n  -- An offer's registry name, rebuilt from its prefix, the fingerprint the\n  -- name carried (\"\" in the older form) and its node (`ap_name`).\n  pfn offer_name(prefix : String, ofp : String, node_id : String) : String do\n    if ofp == \"\" do prefix ++ node_id else prefix ++ ofp ++ \"/\" ++ node_id end\n  end\n\n  -- A node's name for messages: its member name, else (certificate mode)\n  -- the name its verified certificate gives, else its id.\n  pfn node_label(node : Cap(ClusterNode.Live), node_id : String) : String do\n    match ClusterNode.name_of(node, node_id) do\n      Some(nm) -> if nm == \"\" || nm == node_id do cert_label(node, node_id) else nm end\n      None -> cert_label(node, node_id)\n    end\n  end\n\n  pfn cert_label(node : Cap(ClusterNode.Live), node_id : String) : String do\n    match ClusterNode.peer_cert(node, node_id) do\n      Some(c) ->\n        let nm = NodeCert.node_name(c.node)\n        if nm == \"\" do node_id else nm end\n      None -> node_id\n    end\n  end\n\n  -- [why] so far, and one more reason.\n  pfn and_why(why : String, more : String) : String do\n    if why == \"\" do more else why ++ \"; \" ++ more end\n  end\n\n  -- Invite the candidates for [role] in turn until one accepts: Ok(its pid),\n  -- or Err(every refusal, \"; \"-separated, or why there was none).\n  --\n  -- ONE recursive function, not a mutually recursive pair: the mutual pair\n  -- this was first written as hit a mutual-TCO loop that freed an argument it\n  -- was about to forward (ASAN: a use-after-free on `why`). That is fixed --\n  -- the release is now deferred to the loop's exit\n  -- (specs/progress/2026-09-26-mutual-tco-forwarded-arg.md) -- so the shape\n  -- is only a matter of style now.\n  pfn invite_role(node : Cap(ClusterNode.Live), prefix : String, sid : String, fp : String, reply : GlobalPid.Pid, irole : Int,\n                  answers : Vault(String), budget : Vault(Int), cands : List((GlobalPid.Pid, String, List(String))), why : String)\n      : Result((GlobalPid.Pid, String), String) do\n    match cands do\n      Nil -> Err(if why == \"\" do \"no access point is registered\" else why end)\n      Cons((g, ofp, vouch), rest) ->\n        if Vault.get_or(budget, \"left\", 0) <= 0 do Err(and_why(why, \"no answer within the setup time\"))\n        else\n          -- Ok(None) accepts; Ok(Some(reason)) moves on to the next candidate.\n          let outcome = match ClusterNode.send_msg(node, g, \"SessionAP.Invite\", encode_invite(sid, fp, reply, irole, vouch), NodeQueue.Unbounded) do\n            Err(_) -> Some(node_label(node, g.node_id) ++ \" is unreachable\")\n            Ok(_) ->\n              match await_answer(node, answers, sid, g, offer_name(prefix, ofp, g.node_id), budget) do\n                Answered(v) ->\n                  if v == \"\" do None\n                  else Some(node_label(node, g.node_id) ++ \" refused: \" ++ v) end\n                OfferGone ->\n                  -- Withdrawn in case it accepted just before it closed.\n                  let _ = ClusterNode.send_msg(node, g, \"SessionAP.Withdraw\", encode_sid(sid), NodeQueue.Unbounded)\n                  Some(node_label(node, g.node_id) ++ \" \" ++ offer_closed())\n                NoAnswer ->\n                  let _ = ClusterNode.send_msg(node, g, \"SessionAP.Withdraw\", encode_sid(sid), NodeQueue.Unbounded)\n                  Some(node_label(node, g.node_id) ++ \" did not answer\")\n              end\n          end\n          match outcome do\n            None -> Ok((g, ofp))\n            Some(reason) -> invite_role(node, prefix, sid, fp, reply, irole, answers, budget, rest, and_why(why, reason))\n          end\n        end\n    end\n  end\n\n  pfn withdraw_all(node : Cap(ClusterNode.Live), sid : String, accepted : List(GlobalPid.Pid)) : () do\n    let _ = List.map(accepted, fn g ->\n      ClusterNode.send_msg(node, g, \"SessionAP.Withdraw\", encode_sid(sid), NodeQueue.Unbounded))\n    ()\n  end\n\n  -- Fill every role in [roles] from its offers: Ok(the accepted offers), or\n  -- Err((role, why, accepted so far)). Any node may play several roles of\n  -- one session, the initiator's own included -- each party is its own\n  -- endpoint, and frames between two on one node take the loopback link --\n  -- so [used] (nodes to skip) is empty unless a caller wants otherwise.\n  -- [names] is the protocol's role-name table (step 11b's checks).\n  pfn fill_roles(node : Cap(ClusterNode.Live), proto : String, names : List((String, Int)), sid : String, m : ApMix,\n                 reply : GlobalPid.Pid,\n                 answers : Vault(String), budget : Vault(Int), roles : List(Int), n : Int,\n                 used : List(String), accepted : List(GlobalPid.Pid))\n      : Result(List(GlobalPid.Pid), (Int, String, List(GlobalPid.Pid))) do\n    match roles do\n      Nil -> Ok(accepted)\n      Cons(r, rest) ->\n        let (cands, skipped) = candidates(node, proto, names, r, used, n, m)\n        match invite_role(node, ap_prefix(proto, r), sid, m.fp, reply, m.me, answers, budget, cands, skipped) do\n          Err(why) ->\n            -- \"closing\" is an offer being replaced (`close_offer` right after\n            -- a re-offer, e.g. a hosting actor moving a role to a new protocol\n            -- version): its replacement's registration may not have reached\n            -- this node yet, so look again after a moment, within the setup\n            -- time, rather than report the role unfilled.\n            -- So is an offer that closed before it answered (OfferGone).\n            let replaced = String.contains(why, \"refused: closing\") || String.contains(why, offer_closed())\n            if replaced && Vault.get_or(budget, \"left\", 0) > 100 do\n              sleep_ms(100)\n              let _ = Vault.incr(budget, \"left\", 0 - 100)\n              fill_roles(node, proto, names, sid, m, reply, answers, budget, roles, n, used, accepted)\n            else Err((r, why, accepted)) end\n          Ok((g, ofp)) ->\n            -- The session's second fingerprint, once an offer at one joins.\n            let m2 =\n              if ofp == m.fp || m.other != \"\" do m\n              else\n                let older = List.any(m.rows, fn row -> match row do (_, fps) -> List.member(fps, ofp) end)\n                { m with other: ofp, older: older }\n              end\n            fill_roles(node, proto, names, sid, { m2 with filled: Cons((r, ofp), m2.filled) }, reply, answers, budget, rest, n,\n                       used, Cons(g, accepted))\n        end\n    end\n  end\n\n  doc \"\"\"\n  Start one session of protocol [proto] in role [my_role] on the cluster\n  node [node], filling every role in [others] (all the other roles) from the\n  access points that offer it (`offer_role`). Mints a fresh session id (this\n  node, its creation, a counter: never reused, so a restarted or partitioned\n  node cannot be addressed by an old session), invites one offer per role --\n  an offer on this node first, then the others -- moving to the next\n  offer on a refusal or no answer, all within the setup time\n  (MARCH_SESSION_CONNECT_MS, 20 s). Only offers whose version may form a\n  session with this one are invited (build step 9): the same fingerprint, an\n  older one [compat] (the generated `<P>_Msg.compat_by_role()`) accepts for\n  every role at this fingerprint, or an unknown one that decides for itself;\n  a session holds at most two fingerprints. Then runs [body] as\n  `run_cluster` does.\n  `Err(NoOffer(role, why))` if a role could not be filled; the offers that\n  had accepted are withdrawn. The generated `<P>_Run.initiate_<Role>`\n  supplies the protocol, its role-name table [roles], the role, peers and\n  other roles.\n\n  In certificate mode (step 11b) an offer whose node's certificate does not\n  name \"Proto.Role:offer\" is skipped before any invitation and listed in\n  NoOffer's reasons; each offer checks this node's certificate names\n  \"Proto.Role:initiate\" for [my_role] and refuses otherwise; and once formed,\n  every role's endpoint must be on a node certified for that role.\n  \"\"\"\n  fn initiate(io : Cap(IO), node : Cap(ClusterNode.Live), proto : String, fingerprint : String,\n              roles : List((String, Int)), compat : List((Int, List(String))), my_role : Int,\n              peers : List(Int), others : List(Int), on_close : Int -> Unit, body : Cap(Session.Live) -> Unit)\n      : Result(Session.Outcome, RunError) do\n    -- Counted from the invitations on: a session still forming when a\n    -- SIGTERM drain starts is waited for too (its offers refuse or it forms).\n    -- Once the drain has started, a new one is refused outright: under\n    -- continuous traffic the count otherwise never reached zero and every\n    -- drain ran to its hard deadline (specs/progress/2026-10-13-topology-\n    -- drain-continuous-initiators.md).\n    if refusing_initiations(node) do Err(RunError.Left(\"draining\"))\n    else counted(node, fn () -> initiate_counted(io, node, proto, fingerprint, roles, compat, my_role, peers, others, on_close, body)) end\n  end\n\n  pfn initiate_counted(io : Cap(IO), node : Cap(ClusterNode.Live), proto : String, fingerprint : String,\n                       roles : List((String, Int)), compat : List((Int, List(String))), my_role : Int,\n                       peers : List(Int), others : List(Int), on_close : Int -> Unit, body : Cap(Session.Live) -> Unit)\n      : Result(Session.Outcome, RunError) do\n    -- The first role to fill has no offer registered anywhere: `fill_roles`\n    -- would fail on it at once with this same error, so say it before\n    -- minting a session. A caller that retries until an offer appears (the\n    -- control plane's Agent with no leader, every 5 s) otherwise spawned an\n    -- inbox actor and two tables per attempt, and a killed actor's state\n    -- record is not released in a --hot-reload build: one object per try.\n    match others do\n      Cons(r, _) ->\n        if no_offer_named(node, proto, r) do Err(NoOffer(r, \"no access point is registered\"))\n        else initiate_forming(io, node, proto, fingerprint, roles, compat, my_role, peers, others, on_close, body) end\n      Nil -> initiate_forming(io, node, proto, fingerprint, roles, compat, my_role, peers, others, on_close, body)\n    end\n  end\n\n  pfn no_offer_named(node : Cap(ClusterNode.Live), proto : String, r : Int) : Bool do\n    let prefix = ap_prefix(proto, r)\n    not(List.any(ClusterNode.names(node), fn name -> String.starts_with(name, prefix)))\n  end\n\n  pfn initiate_forming(io : Cap(IO), node : Cap(ClusterNode.Live), proto : String, fingerprint : String,\n                       roles : List((String, Int)), compat : List((Int, List(String))), my_role : Int,\n                       peers : List(Int), others : List(Int), on_close : Int -> Unit, body : Cap(Session.Live) -> Unit)\n      : Result(Session.Outcome, RunError) do\n    let n = ClusterNode.next_id(node, \"ap_sessions\")\n    let sid = ClusterNode.node_id(node) ++ \".\" ++ int_to_string(ClusterNode.creation(node)) ++ \".\" ++ int_to_string(n)\n    let inbox = spawn(ApInbox)\n    let answers = answers_table()\n    let budget = Vault.new(\"session_ap_budget_\" ++ sid)\n    let t = connect_ms()\n    Vault.set(budget, \"left\", if t > 0 do t else 3600000 end)\n    let key = ClusterNode.route_session(node, pid_to_int(inbox), fn d -> inbox_frame(answers, sid, d))\n    let reply = ClusterNode.global_pid(node, pid_to_int(inbox))\n    let mix = { fp: fingerprint, rows: compat, me: my_role, other: \"\", older: false, filled: Nil }\n    let filled = fill_roles(node, proto, roles, sid, mix, reply, answers, budget, others, n, Nil, Nil)\n    ClusterNode.unroute(node, key)\n    -- The inbox has answered its one purpose; left alive it was one actor\n    -- leaked per initiated session.\n    kill(inbox)\n    -- So has the budget's table, which only this task reads; never closed,\n    -- it was one more per initiated session. The answers live in the shared\n    -- table, which a late Answer may still be writing (`answers_table`).\n    forget_answers(answers, sid)\n    Vault.close(budget)\n    match filled do\n      Err((role, why, accepted)) ->\n        withdraw_all(node, sid, accepted)\n        Err(NoOffer(role, why))\n      Ok(_) -> run_cluster_with(io, node, my_role, peers, sid, on_close, body, fn _ -> false,\n                                ap_holder_check(node, proto, roles))\n    end\n  end\nend\n";
